window.WEEK_REGISTRY = [{"key":"0622-0628","meta":{"weekLabel":"2026年第26周","range":"2026.06.22 – 2026.06.28","generatedAt":"2026-07-03","sources":[{"name":"UA 内容评论区","detail":"小红书 / 抖音 / 快手，共 293 条评论，情感分布：负向 147 · 正向 146","tag":"评论区"},{"name":"生态作者集中反馈","detail":"供应商整理 Excel，139 条原始反馈（含多位签约/直播作者集中意见）","tag":"生态作者"}],"sentiment":{"pos":146,"neg":147,"neu":0,"total":293},"isBaseline":true},"modules":[{"key":"biz","name":"商业化","color":"#c25b6e","desc":"抽卡 / 稀世 / 定价 / 兑换 / 付费获取体验"},{"key":"activity","name":"活跃活动","color":"#e8734a","desc":"舞团 / 派对 / 榜单 / 赛事 / 社区玩法活跃度"},{"key":"ip","name":"市场IP","color":"#d4a24e","desc":"题材 / 联动 / 服装设计方向 / 热点跟进"},{"key":"system","name":"本地化（系统玩法）","color":"#5b8fa8","desc":"捏脸美颜社 / 染色 / 自定义 / 拍照录制 / 打歌对局 / 穿模 Bug"},{"key":"other","name":"其他","color":"#8a8577","desc":"客户端稳定性 / 外挂举报 / 反馈渠道等"}],"issues":[{"id":"biz-01","module":"biz","priority":"P0","title":"抽卡获取焦虑 · 稀世“绮/皮”兑换与保底诉求强烈","summary":"评论区大量玩家反馈“抽不到、900火苗没出皮、保底节奏、花900不好看也得夸”，对占卜盒子稀世（皮/绮）获取门槛不满；同时希望皮与绮均可用火焰/道具兑换。生态作者建议开放玩家间钻石交易做抽奖出路。","mentions":34,"sources":["评论区","生态作者"],"sentiment":"负","quotes":["900火苗没有皮[哭惹R]","花我900，不好看你也得夸","抽不到不要了，浪费钱","希望皮能兑换就好了 / 皮和绮都是换的","你能玩家和玩家钻石交易就好了，这是抽奖的出路（作者）"],"action":"评估占卜盒子稀世保底与兑换规则透明度；论证“皮/绮双兑换”及玩家交易系统可行性与收入影响。"},{"id":"biz-02","module":"biz","priority":"P1","title":"稀世/黑卡品质感与差异化不足","summary":"作者反馈黑超比红超珍贵却仅多两形态、不配染色；稀世编号缺专属时间/名字；幻名片涵盖所有特效导致“抽到幻名片就收手”，削弱后续抽卡意愿。","mentions":12,"sources":["生态作者"],"sentiment":"负","quotes":["黑超都不配拥有染色功能了","这次稀世编号没有专属时间、名字，之前四个都有","幻名片几乎涵盖所有特效，抽到幻名片就收手了"],"action":"复盘高价值稀世的形态/编号/特效权益梯度，避免顶级道具削弱后续档位吸引力。"},{"id":"biz-03","module":"biz","priority":"P1","title":"348直充 / 舞团 / 展示动作等付费点性价比争议","summary":"月度348直充衣服“丑到下不去手，不如活动送的轻奢”；动作卡贵且不可永久（录素材一次十几张）；点券无用武之地，希望展示动作卡进商城用点券购买。","mentions":10,"sources":["生态作者"],"sentiment":"负","quotes":["每个月348直充的衣服能好看点吗，丑得连活动送的轻奢都不如","动作卡贵、要省着用，改成永久动作卡就好了","展示动作卡放商城用点券买，点券毫无用武之地"],"action":"梳理直充/动作卡定价与永久化选项；盘活点券消耗场景。"},{"id":"biz-04","module":"biz","priority":"P2","title":"重复超凡部件不能一键分解（Bug/体验）","summary":"稀释、黑卡、金门奖池抽到的重复超凡部件（含超凡头发）背包内无法一键分解。","mentions":3,"sources":["生态作者"],"sentiment":"负","quotes":["重复的超凡部件背包里为什么不能一键分解，黑卡金门奖池重复超凡头发也不给一键分解"],"action":"补齐重复超凡部件一键分解入口。"},{"id":"sys-01","module":"system","priority":"P0","title":"捏脸 / 美颜社 / 定制脸系统长期未升级（作者核心诉求）","summary":"多位捏脸作者与直播作者集中反馈：捏脸系统已满足不了需求、定制脸拉条数据太少（瞳孔/脸型/眉峰拉不动）、套模定制脸只能整体不能大调；建议对齐端游拉条精度、丰富脸型与五官单品，并明确“很多玩家因脸不好看放弃抽奖”，直接影响商业化。提了两年仍有脸拉不动。","mentions":28,"sources":["生态作者","评论区"],"sentiment":"负","quotes":["捏脸系统已满足不了日常需求，希望升级（作者·锦鲤）","定制脸瞳孔不能调大小、脸型拉条无变化","希望手游和端游捏脸拉条数据一样多","很多玩家因为脸不好看放弃抽奖，丰富拉条能促进抽奖（作者）","定制款能捏这件事提了两年，有些脸还是拉不动"],"action":"将美颜社/定制脸升级列为跨商业化联合项：细化拉条、丰富脸型与五官单品、对齐端游精度。"},{"id":"sys-02","module":"system","priority":"P0","title":"自定义染色范围窄 + 光效泛滥审美疲劳","summary":"高频诉求：绝大多数服装不可染色/只能染一半/染色区域粗（几处一起染）；红光/珠子光效染任何色不变。玩家与作者普遍要求“别加光效、加染色”，并希望一键隐藏光效（炫舞2曾有）。戏服若能自定义染色可极大扩展玩法。","mentions":24,"sources":["生态作者","评论区"],"sentiment":"负","quotes":["炫舞能不能所有衣服都可以自定义染色","别加光效，加染色，光效没用，审美疲劳","出个隐藏光效的设置，干干净净的","染色希望分区域细分，戏服要能染色玩法就多了","送的粉臻只能染一半"],"action":"扩大可染色范围与分区精度；提供“一键隐藏光效”开关；戏服支持自定义染色。"},{"id":"sys-03","module":"system","priority":"P0","title":"服装/角色穿模严重，影响作者出片","summary":"金标稀世穿模严重、小倩升大体“穿飞了”、自定义部件跟随动作穿模消失，直接影响作者剪辑出片质量。自定义部件“乱跑/乱飞”反复被提。","mentions":14,"sources":["生态作者","评论区"],"sentiment":"负","quotes":["金标稀世穿模严重","小倩升级大体穿模都穿飞了，剪辑视频尴尬","自定义会乱动，希望不要乱飞","做个动作都穿模不见了"],"action":"专项排查高价值稀世/大体升级的穿模；修复自定义部件位移漂移。"},{"id":"sys-04","module":"system","priority":"P1","title":"拍照 / 录制 / MV 能力不足，依赖后期 AI","summary":"手机不支持高清，拍照录视频模糊“全靠后期AI”；炫乐园/游乐园/甄影城不能拍照；希望打歌所有模式像MV一样可自行保存录像、可拉好友进场景替代机器人、拍摄可自定义比例、歌舞剧加绿幕。","mentions":16,"sources":["生态作者","评论区"],"sentiment":"负","quotes":["手机不支持高清，拍照录视频很模糊","炫乐园/游乐园上个拍摄，拍摄可自定义比例","打歌所有模式都能像MV一样对局结束自行保存录像","歌舞剧背景可以加个绿幕"],"action":"提升原生拍照/录制清晰度；扩展可拍照场景；打歌自助录像与场景邀请好友。"},{"id":"sys-05","module":"system","priority":"P1","title":"打歌对局体验：对话框误触 / 分数隐藏 / 发热卡顿","summary":"打歌多指易误触左下角对话框（玩家用布挡住），希望可隐藏/换位/语音转文字；观战与对局希望可隐藏分数便于录屏；打歌“烧内存、手机烫到能煮鸡蛋”。星动珠子间距希望可自定义。","mentions":15,"sources":["生态作者"],"sentiment":"负","quotes":["对局聊天框能取掉吗，打多指歌容易误触，玩家拿布挡着玩","观战/对局希望能隐藏分数，录屏更美观","一打歌手机可以煮熟鸡蛋，太烫了","星动珠子间距希望可自定义调节"],"action":"对局UI（对话框/分数）提供隐藏或自定义；优化打歌性能与发热。"},{"id":"sys-06","module":"system","priority":"P1","title":"占卜盒子 / 掉线卡顿等客户端稳定性问题（本周评论区高频）","summary":"本周评论区“怎么破…卡住了”话题下多名玩家反馈占卜盒子“里外都卡衣服/一个大件没有”；历史反馈中排位卡顿掉线、大退、闪退、争上游/打牌卡死反复出现。女生跳舞名字飞出框（UI Bug）。","mentions":18,"sources":["评论区","生态作者"],"sentiment":"负","quotes":["外面里面都卡衣服[完啦R]（占卜盒子）","里面一个大件没有，衣服卡的死死的","更新之后总是大退掉线 / 三月份版本老是卡住要大退","女的跳舞名字直接飞出框了"],"action":"排查占卜盒子掉落/卡衣服问题；跳舞名字溢出UI修复；持续跟进版本稳定性。"},{"id":"sys-07","module":"system","priority":"P2","title":"自定义头饰/面饰/帽子灵活度与图鉴数据一致性","summary":"希望头饰/帽子/面饰可拆分配件自由移动旋转缩放染色、帽子可调大小；面具希望做成面饰而非手持；戏服希望配片子头、外搭。高定学院男女号图鉴部件数不一致（男少女多）需修复。","mentions":9,"sources":["生态作者"],"sentiment":"负","quotes":["希望所有头饰帽子面饰都可自定义（拆配件、移动旋转缩放染色）","面具为什么是手持，不要手持要面饰","高定学院男号女号部件数应一样，实际女多男少，请修复"],"action":"增强头面饰自定义；修复高定学院图鉴男女部件数差异。"},{"id":"sys-08","module":"system","priority":"P2","title":"大体/小体使用场景与掌上衣柜联动","summary":"宠物/坐骑小体在房间社区不能用大体、单双人大小体不统一；掌上希望能打开自身衣柜自由搭配，减少游戏与掌上来回切换；名片希望加背包/换衣入口。","mentions":8,"sources":["生态作者"],"sentiment":"中","quotes":["宠物小体希望在房间社区也能用大体","掌上能否打开自己的衣柜自由搭配","名片设置个背包按键，在名片就能换衣服"],"action":"打通大小体使用场景与掌上/名片换装入口。"},{"id":"ip-01","module":"ip","priority":"P0","title":"题材单一 · 民族/非遗/戏曲等文化题材呼声高","summary":"作者与玩家反复要求出民族/非遗/戏曲服饰（“说了N遍”“56个民族”），认为泳装/睡衣/亲嘴子题材已审美疲劳；本周评论区亦出现“咋又是泳装”。既有文化传播意义，也能拉动差异化。","mentions":15,"sources":["生态作者","评论区"],"sentiment":"负","quotes":["非遗、民族说了N遍，56个民族那么多，想要苗族服饰","泳装婚纱校服睡衣猫猫狗狗亲嘴子看腻了","咋又是泳装（评论区）"],"action":"规划民族/非遗/戏曲文化题材线；平衡泳装等高转化题材与题材多样性。"},{"id":"ip-02","module":"ip","priority":"P1","title":"追热点滞后 & 联动诉求（ENEMY / 影视戏曲 / 易梦玲等）","summary":"作者指出更新追不上热点（“甄嬛前一年热度，炫舞后一年才出”），建议跟进 ENEMY、影视戏曲热点；评论区出现易梦玲联动服装呼声。希望热点戏服做细致、可进稀世。","mentions":8,"sources":["生态作者","评论区"],"sentiment":"负","quotes":["最近ENEMY那么火，可以出相关服饰，希望跟上脚步","甄嬛是前一年热度，炫舞后一年才出","易梦玲 衣服（评论区）"],"action":"建立热点/联动快速响应机制，缩短从热点到上线周期。"},{"id":"ip-03","module":"ip","priority":"P1","title":"服设创作力 & 建模质感对标竞品诉求","summary":"作者反复要求提升服设创作力、对标“以闪/逆水寒/崽崽”：衣服可自由设计裁切染色、建模跟随身体有拉扯感而非“硬邦邦/铁板披风”、戏服不漏腿尊重传统、男生头发款式少。","mentions":12,"sources":["生态作者"],"sentiment":"负","quotes":["学学逆子，人家哪件衣服不能染，全部可自由设计染色","建模师做的衣服太硬，希望像崽崽跟着身体动作有拉扯感","希望戏服不漏腿，尊重传统文化","男生头发换来换去就那几样"],"action":"提升服设与建模质感（物理跟随、题材多样、男款供给）。"},{"id":"act-01","module":"activity","priority":"P0","title":"舞团玩法奖励单薄 · 活跃度低迷、卖团严重","summary":"作者长文集中反馈：舞团活跃度低、新人不愿入、老玩家退团/卖团，核心是缺留人奖励。建议舞团任务/团贡献可兑换超凡（或大体臻品）套装、提升送物舞团币奖励，以任务驱动活跃与引流。","mentions":10,"sources":["生态作者"],"sentiment":"负","quotes":["建议开放舞团任务兑换超凡套装，用舞团币兑换，盘活舞团","炫舞人员流失太严重，舞团建设太吃力，舞团衣服极丑，好多人卖团","赠送互动的舞团币收益低，难以调动积极性"],"action":"重构舞团奖励体系：高吸引力可兑换奖励 + 提升互动收益，评估引流与商业化平衡。"},{"id":"act-02","module":"activity","priority":"P1","title":"舞团系统体验：舞会卡顿冗长 / 派对管理 / 展示与公告 / 提示","summary":"作者集中反馈舞团系统体验：舞会时长久且卡顿建议改快节奏任务；派对希望上锁防乱打；舞团页面希望自定义人物展示与坑位；公告希望进团弹窗；新人申请/知名度上限缺醒目提示；奖励盒子希望可锁。","mentions":9,"sources":["生态作者"],"sentiment":"负","quotes":["舞会时长太久、过程卡顿，建议换成节奏更快的多人团队打分","为舞团派对增加上锁设置，防止乱打多打","进入舞团时增加公告气泡弹窗","新人申请/知名度上限缺红色提示，经常漏看"],"action":"系统性优化舞团派对/展示/公告/提示体验（可作为舞团专项一并推进）。"},{"id":"act-03","module":"activity","priority":"P1","title":"对战中心 / 排位环境：恶意穿搭卡人、多设备开黑送分","summary":"长文投诉：对战中心排位存在穿超量配饰/大裙摆恶意卡人、组织化多设备双排双人舞撞车、挂机送分破坏公平，设备差者直接卡死。历史亦有外挂脚本、追着卡语音放录音骂人诉求。","mentions":6,"sources":["生态作者"],"sentiment":"负","quotes":["穿花里胡哨恶意卡人上分，组团撞车、多设备双排、挂机送分","排位外挂脚本太多，严重影响排名","追着卡语音放录音、骂人，求优化"],"action":"治理排位恶意行为（配饰渲染上限/举报处置/多开与挂机识别）。"},{"id":"act-05","module":"activity","priority":"P2","title":"常驻玩法/地图长期不更新，社区与街区荒废","summary":"作者反馈对战中心常驻活动衣服几年不更新、社区玩法少、街区荒废；游乐场地图一年没更新（诸神黄昏/躲猫猫等）；语音房希望增加任务兑换座椅/衣服等新玩法。","mentions":6,"sources":["生态作者"],"sentiment":"负","quotes":["对战中心常驻活动衣服几年都不更新，社区玩法不多，街区也荒废了","炫舞游乐场地图更新，一年没更新了，诸神黄昏躲猫猫都更新一下","语音房增加新玩法：任务兑换座椅/大体衣服"],"action":"评估常驻玩法/地图更新节奏与语音房玩法扩展。"},{"id":"oth-01","module":"other","priority":"P1","title":"新品预告/上架时间不固定，福利领取异常","summary":"本周及历史反馈：新品预告不放图直接上视频、视频放完次日不上架第三日才上、臻品盒子活动凌晨更新延迟；3000天庆典新版本福利领取不了。作者认为上新时间不固定影响预期与内容排期。","mentions":7,"sources":["评论区","生态作者"],"sentiment":"负","quotes":["现在公告上新时间不固定，我也不确定了（评论区作者）","新品预告不放图片直接上视频，视频放完第二天不上架第三天上架","3000天庆典福利站新版本福利领取不了"],"action":"规范新品预告与上架时间节奏；排查庆典福利领取Bug。"},{"id":"oth-02","module":"other","priority":"P2","title":"社交/跨区好友位不足、同性伴侣证等社交诉求","summary":"跨区好友位太少（希望加到300）；希望同性可出伴侣证并可长树；游乐园/环球影城任务卡树进不去做不了。","mentions":5,"sources":["生态作者"],"sentiment":"中","quotes":["跨区好友位置太少，希望增加到300","希望同性可以出伴侣证也可以长树","环球影城里面总是挂在树上，进不去，任务做不了"],"action":"评估好友位扩容、社交关系多样性与场景任务卡点修复。"}]},{"key":"0701-0706","meta":{"weekLabel":"2026年 07.01–07.06 期","range":"2026.07.01 – 2026.07.06（近6天）","generatedAt":"2026-07-07","sources":[{"name":"UA 内容评论区","detail":"小红书 / 抖音，共 193 条评论，情感分布：负向 62 · 正向 131","tag":"评论区"},{"name":"生态作者集中反馈","detail":"供应商整理 CSV，共 159 条（作者/资深玩家累积集中反馈，含优化建议 95 · 游戏体验 31 · Bug 12 · 资讯反馈 8 等）","tag":"生态作者"}],"sentiment":{"pos":131,"neg":62,"neu":0,"total":193},"noticeHtml":"本期为<strong>双源</strong>：UA 评论区（193 条）+ 生态作者集中反馈（159 条）。评论区噪声占比极高（约九成为“礼申/求图/贴贴/🉑”互动与抽卡打卡），<strong>实质产品诉求主要来自生态作者反馈</strong>——作者意见集中在系统玩法（捏脸/染色/自定义/穿模）、商业化（奖池性价比/至尊争议/送礼）、活跃（舞团/榜单治理）三大块。下方为两源合并、剔噪后的归纳。带 <strong style=\"color:#e8734a\">✦新</strong> 角标的为<strong>本期新出现</strong>（对比上期 07.01–07.05 未覆盖的议题），未带角标即延续上期已有议题。","isBaseline":false},"modules":[{"key":"biz","name":"商业化","color":"#c25b6e","desc":"抽卡 / 稀世至尊 / 定价 / 兑换交易 / 送礼氪金福利 / 付费获取体验"},{"key":"activity","name":"活跃活动","color":"#e8734a","desc":"舞团 / 派对 / 榜单治理 / 赛事排位 / 社区玩法 / 官号内容 / 任务节奏"},{"key":"ip","name":"市场IP","color":"#d4a24e","desc":"题材方向 / 服设创新 / 联动 / 民族非遗戏曲 / 擦边审美疲劳"},{"key":"system","name":"本地化（系统玩法）","color":"#5b8fa8","desc":"捏脸美颜社 / 染色光效 / 自定义 / 拍照录制 / 打歌对局 / 穿模建模 Bug / 稳定性"},{"key":"other","name":"其他","color":"#8a8577","desc":"AI 宣发货不对板 / 外挂举报 / 反馈渠道等"}],"issues":[{"id":"biz-01","module":"biz","priority":"P0","isNew":false,"title":"抽卡获取焦虑延续 · “抽不到 / 幻不出 / 坚持不下去”","summary":"评论区多名玩家表达获取焦虑：金门定制/占卜稀世“好看却抽不到”、幻卡“还没幻出来”、集齐进度长“我还早着呢……不想坚持了”；作者侧亦提出爆率太低、希望闪耀像臻品甄选长期返场。获取门槛与长线坚持疲劳是延续上期的核心负向。","mentions":10,"sources":["评论区","生态作者"],"sentiment":"负","quotes":["好好看，可惜没抽到[捂脸R]","我的还没幻出来[失望R] / 我还早着呢……不想坚持了","喜欢的我都不配拥有[捂脸R]","建议闪耀跟臻品甄选一样长期全部返场，还是爆率太低了（作者）"],"action":"评估幻卡进度体感、保底透明度与返场机制；关注长线集齐节奏带来的坚持疲劳，可与“皮/绮兑换”诉求合并跟进。"},{"id":"biz-02","module":"biz","priority":"P0","isNew":true,"title":"“至尊”新标价高质低争议 · 超凡与稀世同质、货不对板","summary":"作者集中吐槽新推“至尊”标：奖池贵得离谱却“像塑料纸/塑料袋”，把一套衣服拆开卖、超凡与稀世“一个样只多图鉴”，直播称耗时半年但画面全是 AI、货不对板。多位作者认为新标缺乏与价格匹配的品质与特色，情绪偏激烈。","mentions":9,"sources":["生态作者"],"sentiment":"负","quotes":["至尊噱头听着好看好贵，结果好丑还那么贵，太敷衍，很多玩家在吐槽","把一套衣服拆开来卖，稀世和超凡一模一样，就多了图鉴，奖池还贵得离谱","至尊像塑料纸，细节都做不好，还不如免费稀世做得好","超凡别搞那么敷衍，一对比都不如金标那个奖池"],"action":"复盘“至尊”新标的品质/差异化与定价合理性；对齐宣发（AI 海报）与实际建模，避免货不对板放大付费落差。"},{"id":"biz-03","module":"biz","priority":"P1","isNew":true,"title":"高氪/升钻/氪条福利“越活越回去”，性价比被质疑","summary":"作者反馈氪金福利力度倒退：升紫钻/V20 这种大事只送寒酸奖励“看不起高氪玩家”，钻等级越高送的越差（与他游相反），蜕变臻品/图鉴“一套衣服都舍不得送”，回流一周送 1000 钻反显对比。指向高价值付费用户的获得感缺失。","mentions":6,"sources":["生态作者"],"sentiment":"负","quotes":["升级紫钻这么大个事居然这么小气，看不起高氪玩家","V20 怎么也得送个超凡才说得过去吧，太扣了","别的游戏钻等级越高送越好，炫舞怎么反过来了？","钻19-20就送这东西，可以参考别的游戏升钻怎么送"],"action":"重审高钻等级/氪条奖励梯度，对齐同类竞品的高氪回馈；提升高价值用户的仪式感与获得感。"},{"id":"biz-04","module":"biz","priority":"P1","isNew":true,"title":"钻石/道具交易与重复超凡分解诉求","summary":"作者多次提出希望开放玩家间钻石/道具交易——“拿钻抽自己想抽的，重复的不用分”；同时反馈稀世/黑卡/金门奖池抽到的重复超凡部件（含头发）背包内不能一键分解，体验割裂。属付费产出的资产流通与处置诉求。","mentions":4,"sources":["生态作者"],"sentiment":"负","quotes":["玩家和玩家钻石交易就好了，这是抽奖的出路，重复的也不用分了","重复的超凡部件为什么不能一键分解，黑卡和金门重复超凡头发也不给分解"],"action":"评估可控范围内的资产流通（交易/兑换）与重复部件一键分解，缓解抽卡沉没成本焦虑。"},{"id":"biz-05","module":"biz","priority":"P2","isNew":false,"title":"低价小额活动体验获正向（可复用）· 甄选送抽获好评","summary":"评论区“这6块钱真好玩”对小额活动明确正向；作者亦点名“几次甄选送的1888抽还是不错的”，说明轻付费/高感知让利有良好口碑，是拉新与活跃的低门槛抓手。","mentions":3,"sources":["评论区","生态作者"],"sentiment":"正","quotes":["这6块钱真好玩","做得好的还是要表扬，这几次甄选送的1888抽还是不错的（作者）"],"action":"沉淀小额/高感知让利活动的正向体验，复用到拉新与日常活跃设计。"},{"id":"act-01","module":"activity","priority":"P0","isNew":true,"title":"舞团玩法奖励单薄致卖团/流失 · 强烈诉求超凡衣任务兑换","summary":"作者长文集中反馈：舞团活跃低迷、新人不愿进、老玩家退团卖团，核心是缺留人奖励，恳请开放舞团币兑换超凡/大体臻品套装以盘活舞团任务与引流；并配套多项舞团优化（送礼舞团币奖励、公告气泡弹窗、申请/知名度醒目提示、派对上锁、奖励盒子可多锁、人物展示自定义与坑位增加）。舞团系整体活跃度告急。","mentions":10,"sources":["生态作者"],"sentiment":"负","quotes":["舞团任务可领超凡衣，盘活舞团强引流……人员流失太严重，舞团建设太吃力，好多人卖团","舞团衣服极丑，超凡不行大体臻品也接受","进舞团公告气泡弹窗、新人申请红点、知名度上限提示都要加","派对增加上锁设置，奖励盒子可多锁不上限"],"action":"系统性盘活舞团：评估舞团币兑换高价值时装（超凡/大体臻品）、送礼舞团币激励、公告/申请/知名度提示与派对上锁等管理体验优化。"},{"id":"act-02","module":"activity","priority":"P1","isNew":true,"title":"排位/巅峰赛体验问题 · 匹配难、双模强制、恶意穿搭卡人送分","summary":"作者反馈排位/巅峰赛多项体验问题：连胜后极难匹配只能等人机局；排位强制两模式希望改单选；星动巅峰赛长期无人玩建议换弹珠；并有长文实名投诉“组团穿超凡花里胡哨大裙摆双排双人舞多设备撞车卡人、挂机送分”破坏对局公平与体验。竞技公平与匹配体验是活跃负向重点。","mentions":6,"sources":["生态作者"],"sentiment":"负","quotes":["巅峰赛连胜后非常难进，只能等5分钟进人机局","排位必须两模，建议改成只选一个模式","星动巅峰赛开一年多没人玩，建议换成弹珠","组团穿巨多配饰大裙摆双排双人舞多设备撞车卡人、挂机送分，很影响对局公平"],"action":"优化连胜匹配与巅峰赛人数池、评估排位模式单选；排查恶意穿搭/多设备卡人送分的对局公平治理与举报处置。"},{"id":"act-03","module":"activity","priority":"P1","isNew":true,"title":"社区/游乐场/街区长期不更新，玩法荒废","summary":"作者反馈非抽卡内容长期停滞：小岛新鲜一阵就不更新、美人鱼/游乐场“没人玩却占内存”、街区荒废、对战中心常驻活动衣服几年不更新、语音房玩法单薄；游乐场地图一年未更。呼吁把精力从奖池转向可玩性与社区活跃。","mentions":7,"sources":["生态作者"],"sentiment":"负","quotes":["社区玩法不多，街区也荒废了，常驻活动衣服几年不更新","小岛新鲜一下就扔了不更新，一天到晚变花样出奖池，其他全停滞","炫舞游乐场地图一年没更新了，诸神黄昏/躲猫猫都更新一下","语音房增加新玩法，任务兑换座椅/大体衣服，玩的人会更多"],"action":"制定非抽卡内容更新节奏（社区/游乐场/街区/语音房），把可玩性纳入版本 KPI，缓解“只出奖池”的负面观感。"},{"id":"act-04","module":"activity","priority":"P1","isNew":true,"title":"新品上新/活动时间不规律，公告体验差","summary":"作者反馈上新与活动排期不上心：预告有时不放图直接上视频、视频放完隔两天才上架；臻品盒子活动凌晨五点到很晚仍未更新。运营节奏与公告透明度影响玩家预期与活跃。","mentions":3,"sources":["生态作者"],"sentiment":"负","quotes":["新品上架和预告时间不上心，预告不放图直接上视频，视频放完第二天不上架第三天才上架","今天的臻品盒子活动凌晨五点到现在都没更新好"],"action":"规范上新预告与活动上线时间标准，提升排期透明度与公告一致性。"},{"id":"act-05","module":"activity","priority":"P2","isNew":false,"title":"官号/掌上内容吸引力受质疑（评论区个案，需观察）","summary":"抖音“掌上炫舞关注有礼”官号内容下出现负向“老古董了，没人看了”，指向官号内容形态与掌上活跃度吸引力。本期为个案，建议纳入官号内容提分观察项，跟踪是否成趋势。","mentions":2,"sources":["评论区"],"sentiment":"负","quotes":["[宕机]老古董了，没人看了（抖音·掌上炫舞关注有礼帖）","该玩的还是在玩，就比如我（同帖正向个案）"],"action":"纳入官号内容提分观察；评估掌上/官号内容年轻化表达，跟踪该类负向是否扩大。"},{"id":"act-06","module":"activity","priority":"P2","isNew":false,"title":"任务难度与日常节奏 · 词条任务过难 vs 速刷任务正向","summary":"作者反馈部分活动任务过难——词条刷三天找不到、无法兑换也刷不到，建议开放幻彩石兑换词条；同时评论区对日常“每天五分钟速刷任务”给正向。任务设计在“硬核活动”与“轻量日常”间需平衡。","mentions":3,"sources":["评论区","生态作者"],"sentiment":"负","quotes":["这任务太难了，上周有个词条刷了3天，兑换换不到自己刷也刷不到，拿100幻彩石换一个词条也行（作者）","每天五分钟速刷任务，加油吖（评论区正向）"],"action":"为高难度活动任务提供兜底兑换路径；维持日常任务轻量节奏的正向体验。"},{"id":"ip-01","module":"ip","priority":"P0","isNew":true,"title":"服设创新乏力 · 泳衣睡衣循环、擦边露腿、缺民族/非遗/戏曲题材","summary":"作者高频且强烈反馈题材单一、创新不足：泳衣睡衣来回循环、女装老一套露腿擦边、狐狸人鱼反复出、男生头发换来换去；集中呼吁出民族/非遗/戏曲等文化题材（56 个民族、苗族、戏服），并要求戏服尊重传统不露腿、配套片子头/外搭。设计力与题材多样性是市场IP最大痛点。","mentions":15,"sources":["生态作者"],"sentiment":"负","quotes":["衣服泳衣睡衣泳衣睡衣，服设没新颖的，出点民族服饰，抄抄以闪吧","非遗、民族说了N遍，56个民族那么多，苗族服饰不错，亲嘴子的看腻了","女生老一套露腿设计，来点玄幻的比如女娲？狐狸人鱼来回出","希望戏服不漏腿，尊重传统文化 / 戏服要有片子头、外搭"],"action":"提升服设创新与题材多样性，规划民族/非遗/戏曲等文化向系列；戏服尊重传统形制并配齐头饰外搭。"},{"id":"ip-02","module":"ip","priority":"P1","isNew":false,"title":"古风/占卜穿搭内容口碑好，题材方向获正向印证","summary":"评论区正向集中在古风/占卜系穿搭“美/绝美/两个都美/好美的宝”，达人古风内容高赞，印证古风题材内容力，可作为题材延续与达人共创的正向依据。","mentions":12,"sources":["评论区"],"sentiment":"正","quotes":["绝美 / 好美的宝 / 两个都美","一群又美又仙的古风美女帅哥（达人内容高赞）","团子美 / 别管，超爱"],"action":"延续古风/占卜系穿搭题材与达人共创；将高口碑视觉沉淀为宣发素材。"},{"id":"ip-03","module":"ip","priority":"P1","isNew":true,"title":"稀世光效泛滥、染色范围窄、编号信息缺失","summary":"作者反馈稀世/皮肤“乱七八糟光效”泛滥影响美观、玩家都想要干净款并呼吁一键隐藏光效；染色范围窄——多件不能染、红光/红珠染不掉、送的粉臻只能染一半；本次稀世编号缺专属时间/名字（前几个都有）。视觉与自定义细节拉低稀世体验。","mentions":8,"sources":["生态作者"],"sentiment":"负","quotes":["衣服别加乱七八糟光效，加染色，光效没用审美疲劳，出个一键隐藏光效","染其他颜色还是红色光 / 红色珠子染什么都不变 / 送的粉臻只能染一半","这次稀世编号没有专属时间名字，之前四个都有"],"action":"推进衣服光效可隐藏/减负、扩大可染色范围与分区染色；补齐稀世编号专属信息。"},{"id":"sys-01","module":"system","priority":"P0","isNew":true,"title":"捏脸/美颜社系统长期未升级（作者提了两年）· 直接影响抽奖意愿","summary":"资深作者系统性反馈：捏脸系统满足不了日常需求、多数定制脸瞳孔/脸型拉条拉不动无变化；恳请升级美颜社、细化拉条（眉峰眉尾、多眼型、丰富脸型如刘亦菲/甄嬛），对齐端游拉条数据。作者明确指出“很多玩家因为脸不好看放弃抽奖”，把捏脸质量与商业化直接挂钩。男号定制脸糊弄、白皮脸颊凹陷等问题突出。","mentions":14,"sources":["生态作者"],"sentiment":"负","quotes":["捏脸系统满足不了需求，很多玩家认为脸不好看放弃抽奖，丰富拉条捏脸作者能优化定制脸促进抽奖","定制款能捏提了两年，两年改了有些脸还是拉不动，怎么拉都不动","美颜社提了好多次升级一直不升级","男生定制脸糊弄、太糊，白皮脸颊两边凹陷看着虚"],"action":"立项升级美颜社/捏脸：细化拉条与脸型库、修复拉不动的定制脸、对齐端游数据、补齐男号脸质量——直接联动商业化抽奖转化。"},{"id":"sys-02","module":"system","priority":"P0","isNew":true,"title":"自定义乱跑/穿模严重 · 影响作者出片与建模观感","summary":"作者高频反馈自定义与建模问题：自定义部件“乱跑乱飞”不跟随人物、做动作就穿模消失；金标稀世/小倩大体/假面魅影披风等穿模“穿飞了太丑”，剪辑出片尴尬；建模偏硬、希望像崽崽随动作拉扯。穿模与自定义稳定性是作者出片的硬伤。","mentions":10,"sources":["生态作者"],"sentiment":"负","quotes":["自定义会乱动希望不要乱飞 / 出个自定义还乱跑动","小倩升级大体穿模都穿飞了，剪辑视频挺尴尬太丑 / 金标稀世穿模严重","自定义做不到和人物贴合，做个动作就穿模不见了","建模师做的衣服太硬，希望像崽崽跟着动作拉扯"],"action":"专项修复自定义部件乱跑与稀世/大体穿模；提升建模跟随与柔顺度，保障作者出片质量。"},{"id":"sys-03","module":"system","priority":"P1","isNew":true,"title":"染色/光效自定义诉求 · 全衣可染、分区染色、隐藏光效","summary":"作者强诉求扩大染色自由度：希望所有衣服可自定义染色、染色分区更细（含戏服可染玩法多），并反复要求“一键隐藏光效”还原干净外观（炫舞2曾有）；买了色盘却只有几件能染。自定义染色是提升穿搭表达与留存的高频需求。","mentions":9,"sources":["生态作者"],"sentiment":"负","quotes":["炫舞能不能所有衣服都自定义染色 / 人家逆水寒哪件衣服不能染","染色希望分区域，区域细分多点，戏服能染玩法就多了","出一个一键隐藏光效的，炫舞2有过"],"action":"扩大可染色范围并做分区染色；提供一键隐藏光效开关，对齐竞品自由染色体验。"},{"id":"sys-04","module":"system","priority":"P1","isNew":true,"title":"拍照/录制/MV 自定义能力弱 · 画质模糊、依赖 AI 后期","summary":"作者反馈拍照录制体验落后：炫乐园/游乐园无拍摄、镜头难调、画质模糊“全靠后期软件增高清”；希望打歌/所有模式像 MV 一样可自行录制保存、好友不在线也能拉入场景取代机器人、支持竖屏与自定义比例、歌舞剧加绿幕。内容创作工具链是作者刚需。","mentions":8,"sources":["生态作者"],"sentiment":"负","quotes":["炫乐园上个拍摄，拍照太模糊全靠后期软件增高清","打歌希望所有模式像MV一样对局结束可自选保存录像，考虑单机玩家","好友不在线也能点击好友录制，取代机器人影响美观","拍摄自定义比例 / 星穿搭竖屏拍摄 / 歌舞剧背景加绿幕"],"action":"升级拍照录制工具链：提高清晰度、开放各模式自录与保存、支持竖屏/自定义比例与虚拟录制对象，减少对 AI 后期依赖。"},{"id":"sys-05","module":"system","priority":"P1","isNew":true,"title":"打歌对局体验 · 聊天框误触、隐藏分数、发热、皮肤少","summary":"作者反馈打歌对局多处体验问题：左下角聊天框打多指歌易误触（有人拿布挡着玩）、希望可隐藏/改语音转文字；观战与录屏希望可隐藏分数更美观；打歌烧内存发热“能煮鸡蛋”；星动珠子间距希望自定义；除星动外模式皮肤少（传统仅一个还要付费）。","mentions":8,"sources":["生态作者"],"sentiment":"负","quotes":["对局聊天框能取掉吗，打多指歌容易误触，好多玩家拿布挡着玩","观战/录屏希望隐藏分数更美观","打歌烧内存，一打歌手机可以煮熟鸡蛋，太烫了","星动珠子间距希望自定义 / 其它模式也换个皮肤"],"action":"优化打歌 UI（聊天框可隐藏/转文字、分数可隐藏）、排查发热性能、开放珠距自定义与更多模式皮肤。"},{"id":"sys-06","module":"system","priority":"P1","isNew":true,"title":"大体/小体一致性 · 宠物坐骑/交互设施大体不通用","summary":"作者反馈大体/小体割裂：宠物坐骑单人是小体、双人才大体，希望单双人都能大体；游乐园部分交互设施可用变身大体、部分不行，希望统一通用；星穿搭小体动作仅升级两个希望全部升级。形态一致性影响展示与体验统一。","mentions":5,"sources":["生态作者"],"sentiment":"负","quotes":["宠物坐骑单人小体双人大体，不能单双人都大体吗","游乐园部分交互设施能用大体部分不行，希望都调整为通用","星穿搭小体动作只升级两个，希望后续全部升级"],"action":"统一大体/小体在宠物坐骑、游乐园交互设施、星穿搭动作上的可用性。"},{"id":"sys-07","module":"system","priority":"P1","isNew":true,"title":"自定义动作诉求 · 口令/视频生成、双人动作、永久动作卡","summary":"作者多次提出自定义动作能力：下指令/导入视频自动生成动作（含嘴巴能动）、增加双人情侣动作卡与名片静态动作卡；并反馈动作卡贵/一次性、录素材消耗大，希望改永久动作卡、动作免费、展示动作卡上架用点券购买盘活点券。","mentions":6,"sources":["生态作者"],"sentiment":"负","quotes":["可以自定义动作，下指令自动生成，嘴巴也能动 / 导入视频同步动作","来点双人情侣动作卡、名片不动的动作卡","动作卡贵又一次性，录一次素材花十几个，改成永久动作卡就好了"],"action":"评估自定义动作生成与双人动作供给；优化动作卡计费（永久化/点券购买），降低创作消耗。"},{"id":"sys-08","module":"system","priority":"P1","isNew":false,"title":"客户端稳定性 · 卡顿/闪退/掉线/超凡越穿越卡","summary":"评论区与作者均有稳定性反馈：更新后大退掉线、争上游/打牌卡死、三月版本反复卡住要大退、排位卡顿延迟一天卡死数次；角色首饰越多/越超凡越卡（换高奢即好转）。稳定性与性能是跨源共性负向，建议持续监控修复。","mentions":8,"sources":["评论区","生态作者"],"sentiment":"负","quotes":["更新之后总是大退掉线 / 三月版本老是卡住要大退，能不能测试好再上线","排位卡顿延迟太大，一天卡死最少三次","首饰越多越超凡越卡，换了高奢瞬间好了点","[宕机]（评论区个案吐槽）"],"action":"持续排查卡顿/闪退/掉线与超凡部件性能开销；加强版本上线前测试，减少“上线即卡”。"},{"id":"sys-09","module":"system","priority":"P2","isNew":true,"title":"图鉴/背包/交互零散 Bug 与体验优化","summary":"作者反馈一批零散 Bug 与体验点：定制脸占用服饰图鉴（希望单独图鉴）、高定学院男女号部件数不一致、发型带不出衣柜、环球影城挂树上进不去、戴稀世配件佩戴图鉴卡住、名片增加背包按键、掌上打开衣柜自由搭配、歌曲收藏分类、跨区好友位过少、同性伴侣证等。数量多但单点强度较低。","mentions":12,"sources":["生态作者"],"sentiment":"负","quotes":["请把定制脸移出服饰图鉴，单独给一个图鉴","高定学院女号比男号部件多，希望修复至少一样多","发型带不出衣柜 / 环球影城挂树上进不去任务做不了","掌上能否打开自己衣柜自由搭配，不然又上游戏又去掌上很麻烦"],"action":"批量收敛系统零散 Bug 与小体验优化（图鉴归类、发型/背包、掌上衣柜、收藏分类、好友位、伴侣证等），排优先级迭代。"},{"id":"oth-01","module":"other","priority":"P1","isNew":true,"title":"AI 宣发货不对板 · 海报好看建模撑不起，观感似“诈骗”","summary":"作者集中批评宣发过度依赖 AI：海报/直播画面全 AI、货不对板“太假像诈骗”，实际人物与衣服和封面半毛关系没有，甚至用上隔壁角色的脸。建议要么真实呈现、要么把 AI 能力真正做进游戏（自定义妆容染色）。这是横跨市场与信任的品牌观感问题。","mentions":5,"sources":["生态作者"],"sentiment":"负","quotes":["AI太狠了货不对板，海报画得好看但建模撑不起来","都AI的不是炫舞了太假，第一感觉就是诈骗，人物衣服根本不是这样","直播画面全是AI，都把隔壁秦彻的脸用上了"],"action":"规范宣发素材真实性（AI 使用披露/对齐实机），或将 AI 能力落到游戏内自定义，修复品牌信任。"},{"id":"oth-02","module":"other","priority":"P1","isNew":true,"title":"外挂/语音骚扰治理诉求","summary":"作者反馈治理问题：排位外挂脚本多严重影响排名（希望恢复18/19年环境）、部分玩家追着卡语音放录音骂人。属安全与社区秩序治理，影响核心玩法公平与社交体验。","mentions":3,"sources":["生态作者"],"sentiment":"负","quotes":["排位外挂脚本太多严重影响排名，建议恢复18/19年几乎无外挂的环境","部分玩家追着卡语音放录音骂人，求优化"],"action":"加强反外挂与语音骚扰治理及举报处置，维护竞技公平与社区秩序。"}]},{"key":"0706-0712","meta":{"weekLabel":"2026年 07.06–07.12 期","range":"2026.07.06 – 2026.07.12（本周7天）","generatedAt":"2026-07-13","sources":[{"name":"UA 内容评论区","detail":"小红书 / 抖音 / B站，共 251 条评论（跨快照去重），情感偏负向","tag":"评论区"},{"name":"UA 内容作品表","detail":"本周全平台 9788 个作品声量聚合（播放 1428万+ · 评论 11.2万+ · 点赞 42万+），补充内容侧维度","tag":"内容声量"}],"sentiment":{"pos":42,"neg":62,"neu":147,"total":251},"contentVolume":{"works":9788,"play":14348515,"like":424361,"comment":111996,"share":17535,"byChannel":[{"ch":"小红书","works":4443,"comment":43874,"like":187102,"play":0},{"ch":"抖音","works":3000,"comment":53162,"like":140779,"play":6893414},{"ch":"快手","works":1990,"comment":14032,"like":83704,"play":7373344},{"ch":"微博","works":272,"comment":134,"like":218,"play":10631},{"ch":"B站","works":83,"comment":794,"like":12558,"play":71116}]},"noticeHtml":"本期以 <strong>UA 评论区</strong>为主源（本周监控清单已抓到本周新帖，共 251 条评论），辅以 <strong>content 作品表</strong>的内容声量数据（全平台 9788 个作品）。评论区噪声仍极高（约九成为“收/礼申/求/好看/胖墩墩”打卡互动），已人工剔噪。<strong>本周核心实质信号是抽卡「0配件/配件不齐」焦虑集中爆发</strong>——小红书“抽奖｜500多次0配件”帖下大量真实吐槽（1150次无大件、4000块好久没上头）。本期<strong>无新的生态作者 CSV</strong>，故上期作者侧的系统玩法/服设诉求作为<strong>延续议题</strong>保留跟踪。带 <strong style=\"color:#e8734a\">✦新</strong> 角标的为本期新出现（对比上期 07.01–07.06）。","isBaseline":false},"modules":[{"key":"biz","name":"商业化","color":"#c25b6e","desc":"抽卡 / 稀世至尊 / 定价 / 兑换交易 / 送礼氪金福利 / 付费获取体验"},{"key":"activity","name":"活跃活动","color":"#e8734a","desc":"舞团 / 派对 / 榜单治理 / 赛事排位 / 社区玩法 / 官号内容 / 任务节奏"},{"key":"ip","name":"市场IP","color":"#d4a24e","desc":"题材方向 / 服设创新 / 联动 / 民族非遗戏曲 / 擦边审美疲劳"},{"key":"system","name":"本地化（系统玩法）","color":"#5b8fa8","desc":"捏脸美颜社 / 染色光效 / 自定义 / 拍照录制 / 打歌对局 / 穿模建模 Bug / 稳定性"},{"key":"other","name":"其他","color":"#8a8577","desc":"AI 宣发货不对板 / 外挂举报 / 反馈渠道等"}],"issues":[{"id":"biz-01","module":"biz","priority":"P0","isNew":true,"title":"抽卡「0配件/配件不齐」焦虑集中爆发 · 本周核心负向舆情","summary":"小红书“抽奖｜当你500多次0配件，上头后……”帖下集中爆发真实抽卡吐槽，是本周唯一高强度实质负向信号：多名玩家反馈抽了几百上千次仍0配件或配件不齐、大件久久不出，投入四千多元“好久没上头”仍绷不住继续百开。核心痛点从上期“获取焦虑”进一步聚焦到「配件缺失/大件难出/兑换机制」，情绪激烈（多条 sentiment=-1）。","mentions":12,"sources":["评论区"],"sentiment":"负","quotes":["1150次 没有一个大件[失望R]","500多配件不齐很正常，但是0配件我接受不了[哭惹R]","我之前经常抽3000多块钱4000多块钱，这次500多次0配件一下绷不住了，后面一直在百开","我不也是1900次才给一个大件，理智点 / 305次一串葡萄哈哈哈"],"action":"复盘配件/大件掉率与保底机制，评估“0配件”极端体验的兜底（如配件保底、兑换补足）；抽卡是本周唯一真实高强度负向，建议商业化优先响应并对齐奖池透明度。"},{"id":"biz-02","module":"biz","priority":"P0","isNew":false,"title":"「至尊」新奖池机制争议延续 · 玩家自发解说保底/进阶模式","summary":"上期作者侧“至尊标价高质低”争议本周在内容侧延续发酵：出现玩家自发的“至尊奖池解说”高互动内容，逐条拆解新奖池“保底、剔除、兑换、进阶、升级”机制，结论是“只抽奖的话和过去差距不大，无非价位不一样、图鉴多了”。说明至尊新机制的价值感知与定价合理性仍是玩家关注焦点，需持续跟踪。","mentions":6,"sources":["评论区","内容声量"],"sentiment":"负","quotes":["至尊奖池解说，没看懂的看过来：只抽奖和过去差距不大，无非保底、剔除、兑换的模式，区别是价位不一样、衣服图鉴多了、增加了进阶升级（快手高赞解说）","（延续上期作者反馈：至尊噱头贵却敷衍、超凡与稀世同质）"],"action":"延续上期至尊定价/差异化复盘；关注玩家对新奖池机制的价值感知，必要时优化机制透明度与性价比表达。"},{"id":"biz-03","module":"biz","priority":"P2","isNew":false,"title":"低价小额/免费送活动获正向（可复用）· 稀世免费送、送礼获好评","summary":"内容侧多个“稀世免费送/月灵阶免费领”高互动作品（如“忘情流转 抽到帅衣服码帅脸 喜4免申”），玩家参与积极；延续上期“小额活动/甄选送抽”正向口碑，是低门槛拉新与活跃的有效抓手。","mentions":4,"sources":["评论区","内容声量"],"sentiment":"正","quotes":["【忘情流转】抽到很多帅衣服、码了个帅脸 喜4️⃣免🈸（免申时间7.6-7.12）","#QQ炫舞手游稀世免费送 #炫舞手游免费稀世月灵阶（多作者参与）"],"action":"沉淀免费送/小额高感知让利活动的正向体验，复用到拉新与日常活跃设计。"},{"id":"act-01","module":"activity","priority":"P1","isNew":true,"title":"旅拍季/炫音节/万象舞会等活动内容声量活跃","summary":"内容侧本周活动标签密集：#旅拍季 #炫音节 #万象舞会 #音乐季 等被达人广泛带话题，多为穿搭展示与打卡（如“夏日多巴胺”“挑战：仅凭穿搭判断玩家性别”），活动氛围与达人共创热度良好，属正向内容声量。评论区未见对活动机制的实质吐槽。","mentions":5,"sources":["内容声量"],"sentiment":"正","quotes":["夏日多巴胺🧡💛💚 #QQ炫舞手游炫音节 #炫舞手游万象舞会","⚠️挑战：仅凭炫舞穿搭判断玩家性别 #QQ炫舞手游旅拍季"],"action":"延续旅拍季/炫音节等活动的达人共创与话题运营；将高互动活动内容沉淀为宣发与拉新素材。"},{"id":"act-02","module":"activity","priority":"P1","isNew":false,"title":"舞团/社区/赛事等活跃玩法优化诉求（延续上期作者反馈）","summary":"上期生态作者集中反馈的舞团奖励单薄致流失、排位巅峰赛匹配与公平、社区/游乐场长期不更新等活跃痛点，本期评论区无新增信号但问题未闭环，作为延续议题保留跟踪，待新一轮作者反馈或数据补充再更新强度。","mentions":3,"sources":["生态作者"],"sentiment":"负","quotes":["（上期作者）舞团任务可领超凡衣盘活舞团，人员流失严重好多人卖团","（上期作者）巅峰赛连胜后极难匹配、排位强制双模、恶意穿搭卡人送分"],"action":"延续跟踪舞团盘活、排位公平治理、社区/游乐场更新节奏；下期结合新数据判断是否复现升级。"},{"id":"ip-01","module":"ip","priority":"P1","isNew":false,"title":"古风/占卜/穿搭内容口碑延续好 · 达人穿搭高赞","summary":"评论区正向集中在穿搭内容：“都好看/真好看/真不错搭的/绿绿的很安心/紫色很有韵味”，达人古风与今日穿搭内容获高赞好评，延续上期古风题材口碑，印证穿搭内容力，可作为题材延续与达人共创依据。","mentions":8,"sources":["评论区"],"sentiment":"正","quotes":["都好看 / 真好看 / 真不错搭的[赞R]","确实有韵味[飞吻R]（紫色穿搭帖）","哈哈哈，绿绿的很安心（今日穿搭帖）"],"action":"延续古风/占卜/日常穿搭题材与达人共创；将高口碑视觉沉淀为宣发素材。"},{"id":"ip-02","module":"ip","priority":"P1","isNew":true,"title":"捏脸定制内容高互动 · 金门/鲛海沫逝定制脸持续走红","summary":"内容侧本周捏脸定制类作品互动极高（“鲛海沫逝定制2｜甜美款金门脸”1043条评论），玩家对定制脸的搭配与人设高度关注、催更踊跃。这一方面印证捏脸/定制是炫舞核心内容力，另一方面也侧面呼应上期作者“捏脸系统需升级”的诉求——玩家对好脸的需求旺盛。","mentions":6,"sources":["内容声量"],"sentiment":"正","quotes":["【鲛海沫逝定制2｜限🈸7.9-16号】甜美款金门脸，符合清纯人鱼少女人设 #qq炫舞手游捏脸（1043评论）","妹妹说紫色很有韵味💜（定制脸展示帖高互动）"],"action":"延续捏脸定制达人内容运营；结合玩家对“好脸”的旺盛需求，推动捏脸系统能力升级（见系统模块）。"},{"id":"sys-01","module":"system","priority":"P1","isNew":false,"title":"捏脸/美颜社系统升级诉求（延续上期作者反馈）","summary":"上期资深作者系统性反馈的“捏脸系统长期未升级、拉条拉不动、直接影响抽奖意愿”本期无新增评论信号，但结合本周捏脸定制内容的高互动（见 ip-02），玩家对优质捏脸的需求持续旺盛，问题未闭环，作为高价值延续议题保留跟踪。","mentions":4,"sources":["生态作者"],"sentiment":"负","quotes":["（上期作者）捏脸满足不了需求，很多玩家因为脸不好看放弃抽奖","（上期作者）定制款拉条两年拉不动、美颜社提了好多次不升级"],"action":"延续推动美颜社/捏脸系统升级立项（细化拉条、脸型库、修复拉不动定制脸），直接联动商业化抽奖转化。"},{"id":"sys-02","module":"system","priority":"P2","isNew":false,"title":"自定义穿模/染色光效/拍照录制等系统优化（延续上期作者反馈）","summary":"上期作者反馈的自定义乱跑穿模、染色范围窄、一键隐藏光效、拍照录制画质弱、大小体一致性、自定义动作等一系列系统玩法诉求，本期评论区无新增信号，作为延续议题合并保留跟踪，待新作者反馈再拆分更新。","mentions":3,"sources":["生态作者"],"sentiment":"负","quotes":["（上期作者）自定义会乱飞、稀世/大体穿模严重影响出片","（上期作者）希望所有衣服可染色、一键隐藏光效、拍照录制提清晰度"],"action":"延续跟踪自定义穿模修复、染色自由度、光效隐藏、拍照录制工具链升级；下期结合新反馈判断优先级。"},{"id":"sys-03","module":"system","priority":"P2","isNew":true,"title":"打歌发热与图鉴/交互零散体验（低强度个案）","summary":"本周评论区个别提及打歌相关体验（如徽章跑路、火焰用尽等抽卡衍生吐槽），强度较低；结合上期作者反馈的打歌发热、图鉴归类、背包交互等零散优化点，作为低优先级观察项。本期无集中爆发。","mentions":2,"sources":["评论区","生态作者"],"sentiment":"负","quotes":["有次卡徽章也是干到两千多三千不出，只能把最后那点火焰用了[扶额R]","（上期作者）打歌烧内存发热、图鉴/背包零散Bug"],"action":"纳入低优先级观察；延续收敛系统零散Bug与体验优化，无需本期重点投入。"},{"id":"oth-01","module":"other","priority":"P1","isNew":false,"title":"AI 宣发/二创货不对板观感（延续上期，含 AI 标注内容增多）","summary":"上期作者批评的“AI宣发货不对板、观感似诈骗”本期在内容侧有新佐证：content 表本周多个高互动作品标注“内容由AI生成/含AI生成内容”（如“不干活就吃泥巴”“甄嬛传联动”等），AI二创内容占比上升。虽多为达人娱乐二创、非官方宣发，但需关注 AI 内容与实机的一致性预期，避免品牌观感落差。","mentions":4,"sources":["生态作者","内容声量"],"sentiment":"负","quotes":["（上期作者）AI太狠货不对板，海报好看建模撑不起，第一感觉像诈骗","（本周内容）多个高互动作品标注“作者声明：内容由AI生成”"],"action":"规范官方宣发素材真实性（AI使用披露/对齐实机）；关注达人AI二创繁荣带来的预期管理，将AI能力逐步落到游戏内自定义。"}]},{"key":"0713-0719","meta":{"weekLabel":"2026年 07.13–07.19 期","range":"2026.07.13 – 2026.07.19（本周7天）","generatedAt":"2026-07-23","sources":[{"name":"生态作者反馈","detail":"供应商整理 zip：47 张玩家群聊/游戏截图 + 3 段视频，聚焦抽卡机制、任务难度、新品诚意","tag":"生态作者"},{"name":"UA 内容评论区","detail":"小红书 / 抖音，共 238 条评论（快照去重），剔噪后有效负向集中在抽卡卡衣服、福利买不了","tag":"评论区"},{"name":"UA 内容作品表","detail":"本周全平台 10301 个作品声量聚合（播放 1601万+ · 评论 16.6万+ · 点赞 58万+），补充内容侧维度","tag":"内容声量"}],"sentiment":{"pos":145,"neg":18,"neu":75,"total":238},"contentVolume":{"works":10301,"play":16018569,"like":583018,"comment":166134,"share":21828,"byChannel":[{"ch":"小红书","works":4777,"comment":77476,"like":239937,"play":0},{"ch":"抖音","works":3381,"comment":71113,"like":225526,"play":7545046},{"ch":"快手","works":1943,"comment":17098,"like":112307,"play":8434531},{"ch":"微博","works":125,"comment":98,"like":157,"play":7588},{"ch":"B站","works":75,"comment":349,"like":5091,"play":30814}]},"noticeHtml":"本期为<strong>三源交叉</strong>：① <strong>生态作者反馈 zip</strong>（47张玩家群聊/游戏截图 + 3段视频）② <strong>UA 评论区</strong>（238条，剔噪后有效负向少）③ <strong>content 作品声量</strong>（全平台 10301 作品）。评论区噪声仍极高（约七成为“收/礼申/申/y”打卡互动，被算法误判负向），已人工剔噪。<strong>本周核心实质信号是抽卡「卡衣服 / 重复品自动分解狐晶」焦虑升级</strong>——作者群聊“花了6000多、自动分解真恶心把梦幻火焰全剔除只给狐晶”与评论区“给我两个徽章就是不给衣服、所有奖池都卡衣服”双源印证，是上期「0配件焦虑」的<strong>延续升级</strong>。另有<strong>充钻福利在鸿蒙/华为机型买不了</strong>、<strong>任务词条难度过高刷不到</strong>两条集中诉求。带 <strong style=\"color:#e8734a\">✦新</strong> 角标的为本期新出现（对比上期 07.06–07.12）。","isBaseline":false},"modules":[{"key":"biz","name":"商业化","color":"#c25b6e","desc":"抽卡 / 稀世至尊 / 定价 / 兑换交易 / 送礼氪金福利 / 付费获取体验"},{"key":"activity","name":"活跃活动","color":"#e8734a","desc":"舞团 / 派对 / 榜单治理 / 赛事排位 / 社区玩法 / 官号内容 / 任务节奏"},{"key":"ip","name":"市场IP","color":"#d4a24e","desc":"题材方向 / 服设创新 / 联动 / 民族非遗戏曲 / 擦边审美疲劳"},{"key":"system","name":"本地化（系统玩法）","color":"#5b8fa8","desc":"捏脸美颜社 / 染色光效 / 自定义 / 拍照录制 / 打歌对局 / 穿模建模 Bug / 稳定性"},{"key":"other","name":"其他","color":"#8a8577","desc":"AI 宣发货不对板 / 外挂举报 / 反馈渠道等"}],"issues":[{"id":"biz-01","module":"biz","priority":"P0","isNew":true,"title":"抽卡「卡衣服 · 重复品自动分解狐晶」焦虑升级 · 本周核心负向舆情","summary":"生态作者群聊与评论区双源集中爆发：多名玩家反馈奖池「就是卡衣服」——给徽章/头发就是不给衣服；更强烈的吐槽指向「重复品自动分解成狐晶」机制——“重复的直接自动分解成狐晶，难怪看不到”“自动分解真的恶心，把梦幻和火焰全剔除了，只给狐晶”“我已经花了6000多”。是上期「0配件焦虑」的延续升级，痛点从“配件缺失”聚焦到「大件卡池 + 重复品处置机制不透明」，情绪激烈（评论区 sentiment 低至 -0.9994）。","mentions":15,"sources":["生态作者","评论区"],"sentiment":"负","quotes":["（作者群）重复的直接自动分解成狐晶？难怪看不到 / 自动分解真的恶心，把梦幻和火焰全剔除了，只给狐晶 / 我已经花了6000多","给我两个徽章了，就是不给衣服，所有奖池都是，就是卡衣服，我都服了[哭惹R]","怪好的送我两头发，怕我没头 / 前一套我都还没拿到","问题给的还少（作者群吐槽狐晶补偿量）"],"action":"复盘「重复品自动分解」机制的透明度与玩家知情（分解前提示/可选保留），评估大件卡池掉率与保底；抽卡是本周最强真实负向，建议商业化优先响应并对齐奖池与兑换规则表达。"},{"id":"biz-02","module":"biz","priority":"P0","isNew":true,"title":"充钻福利在鸿蒙/华为机型买不了 · 疑似渠道兼容问题（可闭环）","summary":"抖音「充钻福利/钻石薅羊毛」帖下集中出现“为什么买不了，服了”“我也买不了”“华为点不了”“鸿蒙是买不了”“极速版买不了”等吐槽，一名玩家点明“我是鸿蒙，我就能买”反衬部分机型/渠道（华为鸿蒙、抖音极速版）无法购买。属可定位、可闭环的具体福利活动兼容问题，非泛化情绪，建议尽快核查渠道/机型白名单。","mentions":8,"sources":["评论区"],"sentiment":"负","quotes":["为什么买不了，服了 / 我也买不了[不失礼貌的微笑]","礼申 华为点不了好 / 鸿蒙是买不了","你是在抖音极速版还是抖音买啊，极速版买不了的[戳手手]","我搜不到诶 去官方那也没有看到店铺"],"action":"核查充钻福利活动在华为/鸿蒙及抖音极速版的购买链路兼容与店铺可见性；这是可快速定位闭环的具体问题，建议本期解决并在官号回应。"},{"id":"biz-03","module":"biz","priority":"P1","isNew":true,"title":"新品/超凡诚意不足 · 疑似「换标敷衍」价值感质疑","summary":"作者群聊对新品价值感集中质疑：“搞这么大阵仗宣传新品新标，结果就这？”“就多了图鉴 / 就多了个外搭 / 离谱，敷衍也不带这么玩的”“你出超凡好歹出的不一样吧？一模一样换个标这么敷衍了事？”“这次的就是简化版的稀世”。延续上期「至尊噱头贵却敷衍、超凡与稀世同质」争议，本期升级为对新品「换标不换实质」的直接批评，影响付费信任。","mentions":6,"sources":["生态作者"],"sentiment":"负","quotes":["搞这么大的阵仗宣传新品新标，结果就这？","就多了图鉴 / 就多了个外搭 / 离谱，敷衍也不带这么玩的","你出超凡好歹出的不一样吧？一模一样换个标这么敷衍了事？这次的就是简化版的稀世"],"action":"复盘新品/超凡的差异化设计与宣传落差，避免“大阵仗宣发 + 换标微调”的预期管理风险；强化新品在美术/玩法/图鉴上的实质增量与价值表达。"},{"id":"biz-04","module":"biz","priority":"P2","isNew":true,"title":"赠品/福利「诚意不足」情绪 · 送礼观感偏抠","summary":"作者群聊零散吐槽赠送物诚意不足：“就是送的东西要不要再抠一点”“一套衣服都舍不得送吗”“不指望有啥好东西”“咱不说超凡，蜕变臻品送一套会怎样”。强度低于抽卡，属对整体让利力度的情绪表达，可与免费送/福利活动的正向体验（见 biz 历史正向）对照优化。","mentions":4,"sources":["生态作者"],"sentiment":"负","quotes":["就是送的东西要不要再抠一点 / 一套衣服都舍不得送吗","送不送都没所谓了 / 也不指望有啥好东西","咱不说超凡，蜕变臻品送一套会怎样"],"action":"结合免费送/月灵阶免费领等已验证正向活动，适度提升关键节点赠品的感知价值；低优先级，纳入福利节奏优化观察。"},{"id":"act-01","module":"activity","priority":"P0","isNew":true,"title":"任务/词条难度过高 · 刷不到，玩家被迫走互换 · 集中诉求","summary":"作者群聊高频吐槽任务/词条兑换难度过高：“这任务兑换换不到，自己刷也刷不到，不知道整这么高难度是想干啥”“柳清我刷了几十次没刷到，服啦”“上周有个词条我刷了3天”“我衣服刷不到那个沁霜 / 外搭刷不到皓明”，并配“荣耀天网 发布互换需求”截图，说明玩家被迫走玩家间互换。诉求明确：“实在不行买点需要的也可以”“拿100幻彩石换一个词条也行”，指向兑换/保底通道缺失。","mentions":7,"sources":["生态作者"],"sentiment":"负","quotes":["这任务兑换换不到，自己刷也刷不到，不知道整这么高难度是想干啥 / 这任务太难了，策划自己做过吗","柳清我刷了几十次没刷到，服啦 / 上周有个词条我刷了3天","我衣服刷不到那个沁霜 / 外搭刷不到皓明","实在不行买点需要的也可以 / 就是，拿100幻彩石换一个词条也行"],"action":"复盘词条/任务掉率与难度曲线，评估增设「幻彩石兑换指定词条」等确定性兑换通道；玩家自发走互换说明获取路径断裂，建议活跃活动本期优先优化。"},{"id":"act-02","module":"activity","priority":"P1","isNew":true,"title":"旅拍季/炫音节/夏日游音节等活动内容声量活跃","summary":"内容侧本周活动标签密集：#QQ炫舞手游旅拍季 #炫舞狐神白白我 #快手夏日游音节 被达人广泛带话题，穿搭展示与剧情二创踊跃，高播放作品多挂旅拍季话题，活动氛围与达人共创热度良好，属正向内容声量。评论区未见对活动机制的实质吐槽。","mentions":5,"sources":["内容声量"],"sentiment":"正","quotes":["多个高播放作品挂 #QQ炫舞手游旅拍季 #炫舞狐神白白我（旅拍季 UGC 活跃）","#快手夏日游音节 达人剪辑与剧情二创热度高"],"action":"延续旅拍季/夏日游音节等活动的达人共创与话题运营；将高互动活动内容沉淀为宣发与拉新素材。"},{"id":"act-03","module":"activity","priority":"P2","isNew":false,"title":"舞团/社区/赛事等活跃玩法优化诉求（延续上期）","summary":"此前作者集中反馈的舞团奖励单薄致流失、排位巅峰赛匹配与公平、社区/游乐场长期不更新等活跃痛点，本期作者反馈以抽卡/任务为主、未新增舞团赛事信号，问题未闭环，作为延续议题保留跟踪，待新一轮反馈或数据补充再更新强度。","mentions":2,"sources":["生态作者"],"sentiment":"负","quotes":["（历史作者）舞团任务可领超凡衣盘活舞团，人员流失严重好多人卖团","（历史作者）巅峰赛连胜后极难匹配、排位强制双模、恶意穿搭卡人送分"],"action":"延续跟踪舞团盘活、排位公平治理、社区/游乐场更新节奏；下期结合新数据判断是否复现升级。"},{"id":"ip-01","module":"ip","priority":"P1","isNew":false,"title":"天狐御临/狐神题材内容持续高热","summary":"内容侧本周头部作品集中在官方「天狐御临·至尊池」抽奖记录解说（快手 51万播放），玩家自发拆解至尊/夜形态图鉴“集齐远不算毕业”，围绕狐神IP的题材内容力活跃。","mentions":5,"sources":["内容声量"],"sentiment":"正","quotes":["天狐御临｜抽奖记录🎁③至尊篇 集齐图鉴远不算毕业，夜形态进阶真愁人～（快手51万播放）"],"action":"延续狐神IP达人运营；将至尊池高互动解说沉淀为宣发素材，同时关注玩家“集齐≠毕业”的进阶成本感知（联动 biz-01）。"},{"id":"ip-02","module":"ip","priority":"P2","isNew":false,"title":"古风/穿搭/捏脸展示内容口碑延续好","summary":"内容侧穿搭/古风/捏脸展示类作品口碑延续良好，直播捏脸定制（如稀世染色、耳饰细节展示）与今日穿搭内容获稳定互动，延续上期古风题材与捏脸定制口碑，印证穿搭与好脸的内容力，可作为题材延续与达人共创依据。","mentions":5,"sources":["内容声量"],"sentiment":"正","quotes":["炽烈娇艳（直播捏脸展示，耳饰/穿搭细节获观众互动）","至尊稀世染色 / 稀世白狐（高播放展示作品）"],"action":"延续古风/穿搭/捏脸展示题材与达人共创；将高口碑视觉沉淀为宣发素材。"},{"id":"sys-01","module":"system","priority":"P1","isNew":false,"title":"捏脸/美颜社系统升级诉求（延续 · 与抽卡意愿强关联）","summary":"此前资深作者系统性反馈的“捏脸系统长期未升级、拉条拉不动、直接影响抽奖意愿”本期无新增独立信号，但结合本周捏脸定制内容的持续高互动（见 ip-02）与抽卡卡衣服吐槽（biz-01），玩家对“好脸 + 好衣服”的组合需求旺盛，捏脸能力仍是转化关键，问题未闭环，作为高价值延续议题保留跟踪。","mentions":4,"sources":["生态作者"],"sentiment":"负","quotes":["（历史作者）捏脸满足不了需求，很多玩家因为脸不好看放弃抽奖","（历史作者）定制款拉条两年拉不动、美颜社提了好多次不升级"],"action":"延续推动美颜社/捏脸系统升级立项（细化拉条、脸型库、修复拉不动定制脸），直接联动商业化抽奖转化。"},{"id":"sys-02","module":"system","priority":"P2","isNew":false,"title":"自定义穿模/染色光效/拍照录制等系统优化（延续）","summary":"此前作者反馈的自定义乱跑穿模、染色范围窄、一键隐藏光效、拍照录制画质弱、大小体一致性、自定义动作等系统玩法诉求，本期无新增集中信号，作为延续议题合并保留跟踪，待新作者反馈再拆分更新。","mentions":2,"sources":["生态作者"],"sentiment":"负","quotes":["（历史作者）自定义会乱飞、稀世/大体穿模严重影响出片","（历史作者）希望所有衣服可染色、一键隐藏光效、拍照录制提清晰度"],"action":"延续跟踪自定义穿模修复、染色自由度、光效隐藏、拍照录制工具链升级；下期结合新反馈判断优先级。"},{"id":"oth-01","module":"other","priority":"P1","isNew":true,"title":"抽奖动效「华而不实」误导观感 + AI二创内容标注增多","summary":"两条其他向观感问题：① 抖音玩家吐槽极光抽奖动效误导——“那极光抽奖的动静能不能做朴实一些，又不是大奖还整那么华丽，搞得白激动一场！”“5000多抽都没齐”，动效与实际出货落差影响体验；② content 表本周仍出现标注“作品疑似AI合成，请谨慎甄别”的高互动作品，AI二创占比延续，需关注 AI 内容与实机一致性的品牌观感预期。","mentions":4,"sources":["评论区","内容声量"],"sentiment":"负","quotes":["那极光抽奖的动静能不能做朴实一些，又不是大奖还整那么华丽，搞得白激动一场！","极光模拟器5000多抽都没齐 / 最后剩一个我都懒得抽了，主要不想看广告","（内容）高互动作品标注“作品疑似AI合成，请谨慎甄别”"],"action":"评估抽奖动效分级（区分大奖/普通出货）降低误导感；延续关注 AI 二创的预期管理与官方宣发真实性披露。"}]},{"key":"0720-0726","meta":{"weekLabel":"2026年 07.20–07.26 期","range":"2026.07.20 – 2026.07.26（本周7天）","generatedAt":"2026-08-06","sources":[{"name":"UA 内容评论区","detail":"小红书 / 抖音，共 145 条评论（快照去重），剔噪后有效负向集中在鸿蒙买不了、金银门难抽","tag":"评论区"},{"name":"UA 内容作品表","detail":"本周全平台 10096 个作品声量聚合（播放 3371万+ · 评论 33.9万+ · 点赞 117万+），抽卡吐槽与省钱攻略在内容侧高密度出现","tag":"内容声量"}],"sentiment":{"pos":82,"neg":14,"neu":49,"total":145},"contentVolume":{"works":10096,"play":33718593,"like":1170593,"comment":338761,"share":62689,"byChannel":[{"ch":"小红书","works":4582,"comment":0,"like":0,"play":0},{"ch":"抖音","works":3348,"comment":0,"like":0,"play":16345253},{"ch":"快手","works":1984,"comment":0,"like":0,"play":17024163},{"ch":"微博","works":103,"comment":0,"like":0,"play":11518},{"ch":"B站","works":79,"comment":0,"like":0,"play":337659}]},"noticeHtml":"本期为<strong>双源交叉</strong>：① <strong>UA 评论区</strong>（145条，剔噪后有效负向14条）② <strong>content 作品声量</strong>（全平台 10096 作品 · 播放 3371万）。评论区噪声仍极高（约七成为“礼申/我也来/表情”打卡互动，被算法误判负向），已人工剔噪。<strong>本周核心实质信号是抽卡「黑卡/大保底」成本焦虑在内容侧集中爆发</strong>——达人原声“就想要个幻名片，还给我整个大保底，无语”（10.6万播放）、“我宣布黑卡里面才是最难抽的”、“一次都不给我省，你纯保底啊？？？”形成完整证据链；更值得注意的是玩家自发产出大量<strong>省钱攻略与开奖玄学</strong>（“黑卡尊享严选怎么买最划算｜活动免费钻薅羊毛”、“返厂黑猫建议13开/15开/66开”），<strong>攻略化本身就是成本焦虑的行为证据</strong>，同时也是可复用的达人内容形态。<strong>充钻福利鸿蒙/华为机型买不了连续第2期出现</strong>，仍未解决。带 <strong style=\"color:#e8734a\">✦新</strong> 角标的为本期新出现（对比上期 07.13–07.19）。","isBaseline":false},"modules":[{"key":"biz","name":"商业化","desc":"抽卡奖池/ 定价与保底 / 付费福利 / 支付链路"},{"key":"activity","name":"活跃活动","desc":"活动玩法 / 任务门槛 / 奖励节奏 / 参与体验"},{"key":"ip","name":"市场IP","desc":"题材IP / 达人内容 / 二创生态 / 声量表现"},{"key":"system","name":"本地化（系统玩法）","desc":"系统功能 / 玩法机制 / 客户端体验 / 机型兼容"},{"key":"other","name":"其他","desc":"社区氛围 / 客服反馈 / 未归类诉求"}],"issues":[{"id":"biz-01","module":"biz","priority":"P0","isNew":false,"title":"抽卡「黑卡 / 大保底」成本焦虑集中爆发，玩家被迫攻略化","summary":"本期抽卡吐槽从评论区扩散到内容侧头部作品，形成完整证据链：达人「就想要个幻名片，还给我整个大保底，无语」（快手 10.6万播放）、「我宣布黑卡里面才是最难抽的！」、「一次都不给我省，你纯保底啊？？？」。核心痛点是——想要的单品拿不到，却被推到全额大保底，付费与获得感严重脱钩。这是上期「卡衣服 / 重复品自动分解狐晶」焦虑的同源延续，本期表现为对保底机制本身的质疑。","mentions":12,"sources":["内容声量","评论区"],"sentiment":"负","quotes":["就想要个幻名片，还给我整个大保底，无语（快手 10.6万播放 / 33评论）","我宣布黑卡里面才是最难抽的！（快手 3.3万播放）","一次都不给我省，你纯保底啊？？？（快手 2.7万播放 / 35评论）","听劝听劝，黑卡我白了！！！（快手 3.4万播放）"],"action":"复盘黑卡/尊享严选奖池的单品命中率与保底触发分布，评估「想要的拿不到、只能靠全保底」是否为常态；优先考虑定向选择权（自选/兑换券）降低全保底依赖，缓解付费获得感脱钩。"},{"id":"biz-02","module":"biz","priority":"P1","isNew":true,"title":"玩家自发产出「省钱攻略 / 开奖玄学」，攻略化即成本焦虑的行为证据","summary":"本期出现一批高互动的玩家自研攻略内容：「黑卡尊享严选奖池怎么买最划算‖活动免费钻带你薅羊毛省钱抽奖」、「返厂黑猫建议13开，15开，66开」（111评论）、「这次甄选卡动作不好使，卡光好使哦！」（95评论）、「说了很多次自己的甄选宝石不要半场开香槟」。玩家花大量精力研究抽奖时机与省钱路径——这不是噪声，而是成本压力大到需要靠攻略对冲的直接行为证据；同时也说明该内容形态自带高互动，是可复用的达人内容抓手。","mentions":9,"sources":["内容声量"],"sentiment":"中","quotes":["黑卡尊享严选奖池怎么买最划算‖活动免费钻带你薅羊毛省钱抽奖（快手 1.8万播放 / 36评论）","返厂黑猫建议13开，15开，66开（抖音 1.5万播放 / 111评论）","这次甄选卡动作不好使，卡光好使哦！（抖音 1.4万播放 / 95评论）","说了很多次自己的甄选宝石不要半场开香槟！！（快手 11.9万播放）"],"action":"双轨处理：① 把「攻略化程度」作为付费压力的观测指标纳入周监控；② 官方侧考虑输出透明的概率/保底说明与合理规划建议，减少玄学化误导，同时把高互动攻略形态沉淀为达人合作内容模板。"},{"id":"biz-03","module":"biz","priority":"P2","isNew":true,"title":"「金银门 / 差头纱」图鉴难抽，帮抽也不出","summary":"小红书玩家反馈金银门系列与差头纱图鉴出率感知过低：「好难抽，每天帮抽都不出」、「很白了」、「白了金银门，黑其他所有」。属于单奖池出率感知问题，量级小但与 biz-01 的保底焦虑同向。","mentions":4,"sources":["评论区"],"sentiment":"负","quotes":["#银门差头纱图鉴# ，好难抽，每天帮抽都不出","很白了","已经不欧了，布偶全面崩溃"],"action":"核查金银门系列图鉴件的实际出率与玩家感知差距，评估是否需要在图鉴收集侧补充保底或碎片兑换路径。"},{"id":"act-01","module":"activity","priority":"P1","isNew":true,"title":"「稀世免费送 / 曜华阶」活动带动内容传播，是本期正向抓手","summary":"官方活动标签 #QQ炫舞手游稀世免费送 #炫舞手游免费稀世曜华阶 出现在头部作品中（「瓶盖拧不开」抖音 32.5万播放 / 72评论），免费获得稀世的活动设计有效驱动达人与玩家自发传播，与商业化侧的抽卡焦虑形成对冲。属于可复制的正向活动形态。","mentions":5,"sources":["内容声量"],"sentiment":"正","quotes":["瓶盖拧不开 #QQ炫舞手游稀世免费送 #炫舞手游免费稀世曜华阶（抖音 32.5万播放 / 3149赞）","#QQ炫舞手游旅拍季 系列作品持续覆盖头部内容"],"action":"沉淀「免费稀世」活动的传播路径与达人参与方式，作为缓解付费焦虑的常规化活动配置；在抽卡焦虑高发期同步放量，形成节奏对冲。"},{"id":"act-02","module":"activity","priority":"P2","isNew":false,"title":"旅拍季 / 夏日玩水限定持续供给UGC 内容","summary":"#QQ炫舞手游旅拍季 与「夏日玩水限定」主题在本期持续产出内容，评论区互动氛围正向（「夏天就是爱玩水」、「精致从娃娃抓起」、「已经焊在身上了」）。活动主题贴合季节、玩家参与门槛低，UGC 供给稳定。","mentions":6,"sources":["评论区","内容声量"],"sentiment":"正","quotes":["夏日玩水限定｜小朋友的快乐门槛太低啦☀️（评论区正向互动集中）","夏天就是爱玩水","精致从娃娃抓起"],"action":"延续季节性限定主题的内容运营节奏，将低门槛高参与的主题（玩水/旅拍）固化为暑期档常规内容位。"},{"id":"ip-01","module":"ip","priority":"P1","isNew":false,"title":"狐神IP（#炫舞狐神白白我）覆盖全部头部作品，题材内容力稳固","summary":"本期播放 TOP 作品几乎全部带 #炫舞狐神白白我 标签，覆盖抖音/快手双平台：「当初眼瞎了呗哈哈哈」（40.9万播放）、「让你换菜没让你换人啊」（26万播放）、「月圆之夜」（17万播放 / 100评论）、「是你吗！小蝴蝶」（283评论）。狐神IP已成为达人内容的默认题材底座，延续上期热度。","mentions":10,"sources":["内容声量"],"sentiment":"正","quotes":["当初眼瞎了呗哈哈哈 #炫舞狐神白白我（抖音 40.9万播放）","让你换菜没让你换人啊（快手 26万播放）","€AIN•逐月 月下楼阁红衣翩跹逐月起舞（快手 13.9万播放 / 1600赞）"],"action":"持续供给狐神IP的场景/时装素材与话题标签；重点扶持已验证的高产达人（☂゛南梔ꦿ、亦霏、爷青回等），把IP题材优势转化为稳定声量基本盘。"},{"id":"ip-02","module":"ip","priority":"P2","isNew":true,"title":"情感/剧情向内容跑出高互动，是破圈的内容形态机会","summary":"非换装类的情感叙事与反转短剧获得高评论互动：「我赌你的心动长久…爱情是场豪赌」（14.3万播放 / 288评论）、「男生：我只想换不辣的烤串；服务员：收到，马上更换女朋友」（反转短剧，10.2万播放）、B站「归寂：必须发给我的同事尝尝」（3.2万赞 / 627评论）。说明用炫舞场景做情感/搞笑叙事能触达换装核心圈之外的人群。","mentions":6,"sources":["内容声量"],"sentiment":"正","quotes":["我赌你的心动长久，赌你的偏爱专属…爱情是场豪赌（抖音 14.3万播放 / 288评论）","男生：我只想换不辣的烤串；服务员：收到，马上更换女朋友 #反转短剧（快手 10.2万播放）","归寂：必须发给我的同事尝尝（B站 3.2万赞 / 627评论）"],"action":"把情感叙事与反转短剧列为破圈内容方向，定向招募剧情向达人；沉淀「炫舞场景 + 情绪共鸣/反转梗」的内容模板，作为拉新人群触达路径。"},{"id":"sys-01","module":"system","priority":"P0","isNew":false,"title":"充钻福利在鸿蒙/华为机型买不了（连续第2期，仍未解决）","summary":"上期已上报的鸿蒙系统支付问题本期再次出现，且玩家给出了详细的问题现场：「鸿蒙系统买不了，安卓登陆一下就能买了，我手机现在两个炫舞，第一个刚开始卓易通下载的，底下是前段时间下载的，功能都不全，来回切换玩」。玩家被迫双端并行、切换账号才能完成付费，是明确的付费链路阻塞 + 鸿蒙原生版本功能缺失双重问题。","mentions":3,"sources":["评论区"],"sentiment":"负","quotes":["鸿蒙系统买不了，安卓登陆一下就能买了，我手机现在两个炫舞，第一个刚开始卓易通下载的，底下是前段时间下载的，功能都不全，来回切换玩[泪奔]","为什么买不了，服了。#充钻福利 #钻石薅羊毛（帖标题即诉求）"],"action":"【连续2期未闭环，需本期定责】排查鸿蒙 NEXT / 卓易通兼容包的支付通道与功能完整性差异，给出明确的鸿蒙适配时间表；短期至少在鸿蒙端提供可用的付费兜底路径与官方说明，避免玩家自行双端切换。"},{"id":"oth-01","module":"other","priority":"P2","isNew":false,"title":"评论区仍以「礼申/帮抽」型打卡互动为主，噪声占比约七成","summary":"本期 145 条评论中，原始算法标注负向 63 条，人工剔噪后有效负向仅 14 条。绝大部分为「礼申 / 礼貌伸手 / 我也来 / 表情符号」等申领打卡互动，被情感模型误判为负向。这类互动集中在「狐狸许愿日记，需要的来」等送礼帖，本身反映社区活跃度，不应计为负面。","mentions":49,"sources":["评论区"],"sentiment":"中","quotes":["礼申Q区 / 礼貌申 / 我也来（同类打卡互动大量重复）","q区需要的来"],"action":"维持人工剔噪流程；建议向数据侧反馈打卡型短文本的情感模型误判问题，避免负向占比虚高误导判断。同时把「送礼/许愿帖」的高互动特性视为社区活跃资产而非噪声来源。"}]},{"key":"0727-0802","meta":{"weekLabel":"2026年 07.27–08.02 期","range":"2026.07.27 – 2026.08.02（本周7天）","generatedAt":"2026-08-06","sources":[{"name":"UA 内容评论区","detail":"小红书 / 抖音，共 511 条评论（快照去重）；其中 59% 集中在2个申领型互动帖，剔噪后有效负向 20 条","tag":"评论区"},{"name":"UA 内容作品表","detail":"本周全平台 10674 个作品声量聚合（播放 4041万+ · 环比 +20% · 评论 40.6万+），狐神IP跑出234万播放爆款","tag":"内容声量"}],"sentiment":{"pos":152,"neg":20,"neu":339,"total":511},"contentVolume":{"works":10674,"play":40410075,"like":1192676,"comment":406172,"share":76760,"byChannel":[{"ch":"小红书","works":4902,"comment":0,"like":0,"play":0},{"ch":"抖音","works":3501,"comment":0,"like":0,"play":22953796},{"ch":"快手","works":1979,"comment":0,"like":0,"play":17319770},{"ch":"微博","works":213,"comment":0,"like":0,"play":21240},{"ch":"B站","works":79,"comment":0,"like":0,"play":115269}]},"noticeHtml":"本期为<strong>双源交叉</strong>：①<strong>UA 评论区</strong>（511条，环比+250%）② <strong>content作品声量</strong>（10674 作品 · 播放 4041万 · 环比+20%）。<strong>⚠️ 评论量放大须拆分归因</strong>：511条中 <strong>302条（59%）集中在两个申领型互动帖</strong>——「返场金标稀世抽奖方法〔玄学]」164条、「成团活动来啦」138条，两帖平均情感值近0、强负向仅3+1条。<strong>这不是负向爆发，而是申领互动帖带来的量级放大</strong>：单独看=可复制的高互动内容机会，合并看大盘则会让负向占比虚高，两者须分开解读。<strong>本期核心实质信号是成团活动的社交门槛被玩家用「小号绕过」</strong>——高赞攻略“不要自己建团，切没上过号的其他大区…建议创个不玩的大区”被玩家致谢“还真的让我学到了”，说明成团的社交约束被当作障碍而非乐趣。同时<strong>狐神IP跑出234万播放级真实爆款（非买量）</strong>，是本期最大可复制机会。抽卡成本焦虑延续（“新品金银门卡光”“都二百多抽了”“说白了，就是要你们的钱而已”）。带 <strong style=\"color:#e8734a\">✦新</strong> 角标的为本期新出现（对比上期 07.20–07.26）。","isBaseline":false},"modules":[{"key":"biz","name":"商业化","desc":"抽卡奖池 / 定价与保底 / 付费福利 / 支付链路"},{"key":"activity","name":"活跃活动","desc":"活动玩法 / 任务门槛 / 奖励节奏 / 参与体验"},{"key":"ip","name":"市场IP","desc":"题材IP / 达人内容 / 二创生态 / 声量表现"},{"key":"system","name":"本地化（系统玩法）","desc":"系统功能 / 玩法机制 / 客户端体验 / 机型兼容"},{"key":"other","name":"其他","desc":"社区氛围 / 客服反馈 / 未归类诉求"}],"issues":[{"id":"biz-01","module":"biz","priority":"P0","isNew":false,"title":"抽卡成本焦虑延续：新品金银门「卡光」、二百多抽仍未毕业","summary":"连续第3期出现抽卡成本焦虑，本期集中在新品金银门系列：玩家帖「新品金银们卡光慢慢抽吧」聚集57 条评论，实录「嚯，都二百多抽了」、「今天已经阵亡一次了」、「宝怎么卡光」。内容侧同步印证——达人「醉吻红丝｜抽奖记录🎁 黑卡奖池外面算白的，里面真的黑麻了」（快手 24万播放）。另有一条极端负向表态「说白了，就是要你们的钱而已」（情感值 -1.0），是对商业化设计的整体性质疑，需要重视其情绪代表性。","mentions":14,"sources":["评论区","内容声量"],"sentiment":"负","quotes":["嚯，都二百多抽了","今天已经阵亡一次了[捂脸R]","醉吻红丝｜抽奖记录🎁 黑卡奖池外面算白的，里面真的黑麻了（快手 24万播放）","说白了，就是要你们的钱而已（抖音，情感值 -1.0）"],"action":"【连续3期同源信号，建议专项立项】抽卡成本焦虑已从单奖池吐槽升级为对商业化设计的整体质疑。需要给出结构性方案：明确单品可达性（自选/兑换）、优化保底体感、或在高价奖池外提供确定性获取路径，而非逐期缓解。"},{"id":"biz-02","module":"biz","priority":"P1","isNew":false,"title":"「返场金标稀世抽奖方法〔玄学]」单帖聚集164条评论——攻略化延续且已成社区刚需","summary":"上期识别的「攻略化＝成本焦虑行为证据」本期进一步强化：单个玄学抽奖攻略帖聚集 164 条评论，为本期评论量第一，玩家排队「礼申」求攻略。另有「新品金银们卡光慢慢抽吧」57条、玩家致谢「礼伸！终于等到你更新抽奖了，你的技巧真的很有用」。拆开看这是极高互动的内容机会（单帖即贡献本期评论量32%），合并看则说明玩家已把玄学攻略当作抽卡刚需——两个结论都成立，须并列解读。","mentions":164,"sources":["评论区"],"sentiment":"中","quotes":["返场金标稀世抽奖方法〔玄学]（单帖 164 条评论，本期评论量第一）","礼伸！终于等到你更新抽奖了，你的技巧真的很有用","新品金银们卡光慢慢抽吧（57条评论）"],"action":"双轨：① 把这类攻略帖识别为高互动内容资产，纳入达人合作与官方话题共建（承接需求而非放任玄学）；② 同步把「玄学攻略热度」作为付费压力代理指标进周监控，与 biz-01 联动评估。"},{"id":"act-01","module":"activity","priority":"P0","isNew":true,"title":"成团活动社交门槛被玩家用「小号绕过」，攻略获高赞致谢","summary":"本期最重要的产品信号。「成团活动来啦」帖聚集 138 条评论，其中一条玩家自研攻略获得明确正向反馈：「首先不要自己建团，然后切没上过号的其他大区，有人发邀请成团的就去成团，成团后再切主玩的大号区，领取助力礼包，然后就可以买啦…建议宝子们创个不玩的大区，每年都会有成团活动」，评论区致谢「还真的让我学到了，谢谢」。这说明成团活动设计的社交约束（需邀请他人组队）被玩家视为障碍而非乐趣，玩家用小号+跨区切换把社交玩法降解为纯领奖流程——活动的社交裂变目标实质落空。","mentions":138,"sources":["评论区"],"sentiment":"中","quotes":["首先不要自己建团，然后切没上过号的其他大区，有人发邀请成团的就去成团，成团后在切主玩的大号区，领取助力礼包，然后就可以买啦…建议宝子们创个不玩的大区，每年都会有成团活动","还真的让我学到了，谢谢","这个活动在哪 / 这个都有什么 / 缺个最重要的（门槛与信息不清的追问）"],"action":"【建议本期优先复盘】① 复核成团活动的社交约束设计：若裂变目标未达成、反而催生小号跨区套路，应考虑降低强制社交门槛或改为可选加成；② 补齐活动内引导（大量玩家问「活动在哪」「都有什么」，说明入口与规则曝光不足）；③ 评估跨区小号成团是否影响活动成本核算与公平性。"},{"id":"act-02","module":"activity","priority":"P2","isNew":true,"title":"语聊季 / 旅拍季持续供给内容，语聊季出现付费质疑声","summary":"#QQ炫舞手游语聊季 与 #QQ炫舞手游旅拍季 持续覆盖本期内容。但语聊季相关作品「给一次机会BL」评论区出现负向表态（平均情感值 -0.495，含「说白了，就是要你们的钱而已」），该帖为本期唯一整体负向的作品。旅拍季侧则表现健康，多条头部作品均带该标签。","mentions":5,"sources":["评论区","内容声量"],"sentiment":"负","quotes":["给一次机会BL #QQ炫舞手游语聊季（该帖平均情感值 -0.495，本期唯一整体负向作品）","说白了，就是要你们的钱而已"],"action":"单独排查语聊季的付费点设置与玩家感知，确认是否存在「社交玩法强绑付费」的观感；旅拍季模式健康，可作为对照参考。"},{"id":"ip-01","module":"ip","priority":"P0","isNew":true,"title":"★狐神IP跑出234万播放级真实爆款「抓到你了九尾狐大人」，可复制的机会信号","summary":"本期最大亮点。达人「虚伪」作品「抓到你了九尾狐大人」抖音 234万播放 / 1.9万赞 / 473评论，同系列另一条 97万播放；同期「左边剪一下，右边剪一下最后变成秃秃头了哈哈哈」达 247万播放（同一达人两条合计 473万）；快手「亦霏」94万播放。这是真实自发传播的内容爆点（非买量投放），播放量级比上期头部（40万）提升近6倍，直接带动本期全平台播放环比 +20%。狐神IP叠加「趣味互动/反差剧情」的组合被验证有效。","mentions":8,"sources":["内容声量"],"sentiment":"正","quotes":["抓到你了九尾狐大人 #炫舞狐神白白我（抖音 234万播放 / 1.9万赞 / 473评论）","左边剪一下，右边剪一下最后变成秃秃头了哈哈哈（抖音 247万播放）","#QQ炫舞手游 #炫舞狐神白白我 #快手夏日游音节（快手 94万播放 / 1783赞）"],"action":"【机会信号，建议立即拆解复用】① 拆解「抓到你了九尾狐大人」的选题结构（狐神IP人格化 + 互动反差 + 短平快叙事），形成达人内容模板批量复制；② 锁定并深度绑定爆款达人（虚伪、☂゛南梔ꦿ、亦霏）；③ 把该爆款作为狐神IP宣发主素材二次分发，延长长尾。"},{"id":"ip-02","module":"ip","priority":"P2","isNew":true,"title":"跨游戏梗内容（「跟王者过不去了？」）带来外部话题联动","summary":"达人以「跟王者过不去了？」为选题产出内容（抖音 27条评论、平均情感 0.293），借外部游戏话题制造讨论度，评论区互动正向（「还是你两会玩」）。属于借势外部热点的内容形态，量级不大但方向可参考。注：本期另有玩家用炫舞场景制作他游（原神）MMD的作品（28万播放），因属跨IP他游内容、非炫舞本体舆情，不计入本报告。","mentions":3,"sources":["内容声量"],"sentiment":"正","quotes":["跟王者过不去了？#qq炫舞手游 #炫舞狐神白白我（抖音 27评论）","还是你两会玩"],"action":"允许并适度鼓励达人借外部游戏/热点话题造梗，但需设定合规边界（不贬损友商）；同时留意炫舞场景被他游二创借用的现象，可评估是否转化为官方场景开放的宣传点。"},{"id":"sys-01","module":"system","priority":"P1","isNew":true,"title":"捏脸/时装细节体验被高频追问，玩家关注度高于预期","summary":"玩家对外观细节的关注度显著：「旅途咖啡馆｜娃的松弛舒适圈☕」帖聚集 12 条评论且高度正向（平均情感 0.692），但集中在细节追问——「这个鞋子穿起来跟脚嘛」、「鞋子有其他颜色吗？」、「鞋子可以踩脚跟吗」。另有「这个脸是真的很吃皮肤啊！」讨论捏脸与皮肤适配（平均情感 -0.023）。说明玩家对时装的穿着细节与捏脸适配有超出预期的精细需求。","mentions":8,"sources":["评论区"],"sentiment":"中","quotes":["这个鞋子穿起来跟脚嘛/ 鞋子有其他颜色吗？/ 鞋子可以踩脚跟吗","这个脸是真的很吃皮肤啊！","这是稀世绮送的脸"],"action":"① 时装上架时补充细节展示（多角度、配色、穿着效果），减少玩家反复追问；② 评估捏脸与皮肤/时装的适配预览功能，降低「买了才发现不搭」的落差；③ 把配色衍生（同款多色）作为低成本内容供给方向。"},{"id":"oth-01","module":"other","priority":"P1","isNew":true,"title":"★评论量环比+250% 的真实归因：申领型互动帖放大，非负向爆发","summary":"本期评论 511 条（上期 145 条，环比 +250%），算法标注负向 355 条看似激增，但拆分后结论完全不同：302条（59%）集中在两个申领型互动帖——「返场金标稀世抽奖方法〔玄学]」164条 + 「成团活动来啦」138条，两帖平均情感值分别为 0.044 / 0.008（近中性），强负向（低于 -0.5）仅 3 条和 1 条。剔噪后全期有效负向仅 20 条。结论须双向陈述：① 大盘健康度层面，负向并未爆发，占比虚高源于打卡型短文本被情感模型误判；② 单帖机会层面，两个帖各自贡献百条级互动，是真实的高互动内容形态，应作为可复制资产而非噪声。","mentions":302,"sources":["评论区"],"sentiment":"中","quotes":["「返场金标稀世抽奖方法〔玄学]」164条 + 「成团活动来啦」138条 = 本期评论 59%","两帖平均情感值 0.044 / 0.008，强负向仅 3 / 1 条","礼申 / 礼貌伸手 / 李申李申礼申（申领打卡互动大量重复）"],"action":"① 周报口径固定「拆分归因」呈现：大盘负向占比与单帖互动机会分开列示，避免单帖放大误判整体健康度；② 向数据侧反馈申领型短文本（礼申/礼伸/申）的情感误判；③ 把申领型高互动帖形态纳入内容运营可复制清单。"}]},{"key":"0803-0809","meta":{"weekLabel":"2026年 08.03–08.09 期","range":"2026.08.03 – 2026.08.09（本周7天）","generatedAt":"2026-08-18","sources":[{"name":"UA 内容评论区","detail":"小红书 / 抖音 / B站，共 298 条评论（快照去重）；43% 集中在1个申领型互动帖，剔噪后有效负向 16 条","tag":"评论区"},{"name":"UA 内容作品表","detail":"本周全平台 11669 个作品声量聚合（播放 5577万 · 创新高环比+38% · 点赞 137万 · 分享 23.2万）","tag":"内容声量"}],"sentiment":{"pos":152,"neg":16,"neu":130,"total":298},"contentVolume":{"works":11669,"play":55769858,"like":1376659,"comment":357526,"share":232399,"byChannel":[{"ch":"小红书","works":5474,"comment":0,"like":0,"play":0},{"ch":"抖音","works":3754,"comment":0,"like":0,"play":33138151},{"ch":"快手","works":2158,"comment":0,"like":0,"play":22530451},{"ch":"微博","works":206,"comment":0,"like":0,"play":34873},{"ch":"B站","works":77,"comment":0,"like":0,"play":66383}]},"noticeHtml":"本期为<strong>双源交叉</strong>：① <strong>UA 评论区</strong>（298条，剔噪后有效负向16条）② <strong>content 作品声量</strong>（11669 作品 · 播放 <strong>5577万创历史新高，环比+38%</strong>）。<strong>本周核心是一条全新信号：梦幻币（软通货）囤积却无处兑换</strong>——玩家原声“都不好看，我都存了1600了，都没好看的让我兑换”、“扣扣搜搜的存了一千梦幻不知道换啥，想等定制脸，但是感觉兑换的定制脸很久才出，白皮也没见出兑换的”、“扣扣搜搜存了半年左右”。<strong>这与抽卡成本焦虑不同源</strong>：不是抽不到，而是<strong>攒够了也没有想要的出口</strong>，指向兑换池上新滞后。评论量归因：298条中 127条(43%) 来自申领帖「金门定制脸」，属互动放大；<strong>真实负向最集中在「已经存了1000梦幻要换吗」</strong>（34条含5条强负向）。另有金门限量抢购体验差（“金门超难抢，一早上一直刷”）、抽卡被配件卡住（达人实录“银门770次、被配件卡住700多次才出图鉴”）。带 <strong style=\"color:#e8734a\">✦新</strong> 角标的为本期新出现（对比上期 07.27–08.02）。","isBaseline":false},"modules":[{"key":"biz","name":"商业化","desc":"抽卡奖池 / 定价与保底 / 兑换体系 / 付费福利 / 支付链路"},{"key":"activity","name":"活跃活动","desc":"活动玩法 / 任务门槛 / 奖励节奏 / 参与体验"},{"key":"ip","name":"市场IP","desc":"题材IP / 达人内容 / 二创生态 / 声量表现"},{"key":"system","name":"本地化（系统玩法）","desc":"系统功能 / 玩法机制 / 客户端体验 / 机型兼容"},{"key":"other","name":"其他","desc":"社区氛围 / 客服反馈 / 未归类诉求"}],"issues":[{"id":"biz-01","module":"biz","priority":"P0","isNew":true,"title":"★梦幻币囤积无处兑换：攒够了也没有想要的出口（全新信号）","summary":"本期最重要的新问题，与抽卡焦虑不同源。玩家长期积攒软通货「梦幻」却找不到值得兑换的物品：「都不好看，我都存了1600了，都没好看的让我兑换」、「扣扣搜搜的存了一千梦幻不知道换啥，想等定制脸，但是感觉兑换的定制脸很久才出，白皮也没见出兑换的」、「扣扣搜搜存了半年左右」。核心矛盾是兑换池上新严重滞后——玩家想要的定制脸、白皮长期不进池，导致存量货币无出口，反而加剧「换了怕更好的出来」的决策焦虑（「我又怕我换了特效名片又出来了」）。该帖以34条评论聚集本期最多真实负向（5条强负向）。","mentions":16,"sources":["评论区"],"sentiment":"负","quotes":["都不好看，我都存了1600了，都没好看的让我兑换（情感值 -0.998）","扣扣搜搜的存了一千梦幻不知道换啥，想等定制脸，但是感觉兑换的定制脸很久才出，白皮也没见出兑换的","扣扣搜搜存了半年左右","我想换那个夏恋色彩，我又怕我换了特效名片又出来了"],"action":"【建议本期优先处理，成本低见效快】① 盘点梦幻兑换池的上新频率与存量货币规模，评估是否存在大量沉淀无出口；② 优先把玩家点名的高需求品类（定制脸、白皮）排入兑换池，并公布上新预告降低「换了怕后悔」的决策焦虑；③ 考虑增加梦幻的替代消耗途径（如兑换抽卡道具/保底进度）。相比抽卡机制调整，兑换池补货是低成本高感知的改善点。"},{"id":"biz-02","module":"biz","priority":"P1","isNew":false,"title":"抽卡「被配件卡住」问题复现：银门770次、金门740次才搬空","summary":"0713 期识别的「卡衣服/卡配件」问题本期再次由达人实录印证。头部作品「蜃海欢夜｜抽奖记录」（快手 52.8万播放 / 4591赞）自述：银门770次、金门740次全部搬空，「第一发十连就出徽章，紧接着就出衣服，可惜被配件卡住，700多次才出图鉴」。另一条「勿忘三生｜抽奖记录」记录2616次才集齐、仍差黑皮。说明大件先出、小配件长尾卡住的结构性问题依然存在，抬高了实际毕业成本。","mentions":8,"sources":["内容声量","评论区"],"sentiment":"负","quotes":["银门770次，金门740次全部搬空…可惜被配件卡住，700多次才出图鉴（快手 52.8万播放）","勿忘三生｜2616次想要的都有，就差黑皮了（快手 47.4万播放）","我也是怎么抽都不出","我刚开了个男号，也是一样的非，甚至比这个女号还要非"],"action":"复核奖池内「大件 vs 配件/图鉴件」的出率结构，评估长尾配件是否应设独立保底或碎片兑换；这一问题已跨多期复现，建议纳入奖池设计规范而非逐期个案处理。"},{"id":"biz-03","module":"biz","priority":"P2","isNew":true,"title":"金门限量款抢购体验差：一早上一直刷才抢到","summary":"玩家反馈金门限量商品抢购环节体验不佳：「金门超难抢，一早上一直刷」、帖标题即「终于抽到脸了，抢金太难了😭」。属限量供给与抢购交互问题，玩家需长时间手动刷新，付出的是时间成本而非游戏乐趣。","mentions":4,"sources":["评论区"],"sentiment":"负","quotes":["金门超难抢，一早上一直刷","终于抽到脸了，抢金太难了（帖标题即诉求）","礼申 400次唯一的一个大件必须申"],"action":"评估金门限量款的库存投放节奏与抢购交互（是否可改为排队/预约/分批放量），减少玩家无效刷新；若限量为刻意稀缺设计，需评估其带来的挫败感是否超出稀缺价值。"},{"id":"act-01","module":"activity","priority":"P1","isNew":true,"title":"「勿忘三生」稀世上新 + 超凡免费送，带动内容侧播放创新高","summary":"本期官方节奏密集：08.07 稀世「勿忘三生」上新（专属话题标签 #炫舞手游0807稀世勿忘三生 进入头部作品）、同期「超凡免费送」活动落地。内容侧播放冲到 5577万创历史新高（环比 +38%），是免费获取活动叠加新品上新的正向结果。但「帮抽」文化同时暴露落差：「还是帮抽欧啊！超凡免费送了」下有玩家回「我帮抽都是垃圾」（情感值 -1.0）。","mentions":10,"sources":["内容声量","评论区"],"sentiment":"正","quotes":["#炫舞手游0807稀世勿忘三生 覆盖多条头部作品（我有6套房吗？抖音 52.8万播放）","还是帮抽欧啊！超凡免费送了（抖音，帖标题）","我帮抽都是垃圾（情感值 -1.0）"],"action":"延续「新品上新 + 免费获取」的组合节奏，本期已验证能把声量推到历史新高；同时关注「帮抽」形成的对比落差，可考虑给非欧玩家保留确定性兜底获取，避免免费活动反向放大挫败。"},{"id":"act-02","module":"activity","priority":"P2","isNew":true,"title":"线下/非遗亲子向内容自然生长（杭州老街、侠天下避暑）","summary":"本期出现一批与游戏强关联的线下遛娃/避暑向内容，评论区氛围正向（平均情感 0.407~0.68）：「杭州老街📍不用人挤人的非遗遛娃攻略」（18条评论）、「夏日炎炎，带娃躲进侠天下避暑」（9条评论）。用户把游戏内容与真实亲子出行场景结合，是自然生长的泛人群内容形态。","mentions":5,"sources":["评论区"],"sentiment":"正","quotes":["杭州老街📍不用人挤人的非遗遛娃攻略（平均情感 0.407）","夏日炎炎，带娃躲进侠天下避暑（平均情感 0.68）","蛮好闻的，确实没小虫子飞来飞去了"],"action":"留意这类「游戏 + 真实生活场景」的泛人群内容形态，可作为非核心圈层的触达尝试；若有线下IP/文旅合作计划，此类自然内容可作为切入验证。"},{"id":"ip-01","module":"ip","priority":"P1","isNew":true,"title":"情绪叙事内容跑出128万播放爆款，剧情向持续验证有效","summary":"本期头部由情绪/剧情叙事类作品领跑：「《情》#吃饭报备 #抽象」抖音 128.9万播放 / 9184赞 / 376评论、「《关于把宝儿丢餐厅这件事》」80.1万播放 / 6729赞、「被禁锢的天使」36.1万播放 / 147评论、「榴莲吃皮」41.2万播放 / 66评论。延续上期「情感叙事是破圈方向」的判断，本期进一步验证：非换装的叙事/搞笑内容能稳定跑出数十万至百万级播放。","mentions":8,"sources":["内容声量"],"sentiment":"正","quotes":["《情》#吃饭报备 #抽象 #qq炫舞手游00后（抖音 128.9万播放 / 376评论）","《关于把宝儿丢餐厅这件事》（抖音 80.1万播放 / 6729赞）","被禁锢的天使（抖音 36.1万播放 / 147评论）"],"action":"把情绪叙事/短剧列为常规内容供给方向，批量招募剧情向达人；沉淀「炫舞场景 + 情绪共鸣/抽象梗」模板，与狐神IP的换装展示形成互补的双内容线。"},{"id":"ip-02","module":"ip","priority":"P2","isNew":true,"title":"旅拍季仍是声量主力（3295作品/3973万播放），Mini炫开始起量","summary":"本期 #QQ炫舞手游旅拍季 依然是绝对主力：3295 个作品、3973万播放、67.3万赞，占全期播放约七成。同时 Mini炫 主题开始小规模起量（29 作品 / 29.9万播放）、30s秀场挑战试水（8 作品），为下期主线切换埋下伏笔。狐神IP本期回落至 235 作品 / 39.7万播放。","mentions":6,"sources":["内容声量"],"sentiment":"正","quotes":["旅拍季：3295 作品 / 3973万播放 / 67.3万赞（占全期播放约七成）","Mini炫：29 作品 / 29.9万播放（起量前期）","狐神：235 作品 / 39.7万播放（较上期回落）"],"action":"旅拍季进入暑期档收尾阶段，需提前规划接续主题（Mini炫已在试水）；狐神IP热度自然回落属正常周期，可通过新素材或活动重新激活。"},{"id":"sys-01","module":"system","priority":"P2","isNew":true,"title":"外观部件穿脱路径不清晰，玩家找不到卸下入口","summary":"玩家反馈手部装饰无法找到取下的方式：「我想问图一手上装饰那个怎么取下来，我找半天都没有找到取的」，需由其他玩家告知「在配饰里吧」。属于装扮系统的功能可发现性问题，量级小但影响基础体验。","mentions":3,"sources":["评论区"],"sentiment":"中","quotes":["我想问图一手上装饰那个怎么取下来  我找半天都没有找到取的","在配饰里吧（由其他玩家代答）"],"action":"检查装扮界面中配饰类部件的卸下入口是否足够显性（是否需要长按/二级菜单），考虑增加一键卸除或搜索定位，降低查找成本。"},{"id":"oth-01","module":"other","priority":"P1","isNew":false,"title":"评论量归因：43% 来自单个申领帖，负向占比虚高需分开解读","summary":"本期 298 条评论中，算法标注负向 145 条（49%），但强负向（低于 -0.5）仅 8 条，人工剔噪后有效负向 16 条。量级放大来自申领型互动帖「金门定制脸」——单帖 127 条（占43%），平均情感值 0.069 近中性、强负向 0 条，内容几乎全为「礼申/礼伸/礼貌申请」。延续上期约定的拆分归因口径：大盘健康度层面负向未爆发；单帖层面则是稳定的高互动内容资产。","mentions":127,"sources":["评论区"],"sentiment":"中","quotes":["「金门定制脸」单帖 127 条评论（占本期 43%），平均情感 0.069、强负向 0 条","礼申 / 礼伸 / 礼貌申请（同类打卡互动大量重复）","全期强负向（低于 -0.5）仅 8 条"],"action":"维持「拆分归因」呈现口径：大盘负向占比与单帖互动机会分列；继续向数据侧反馈申领型短文本的情感误判问题。申领帖已连续多期成为评论量主要来源，建议纳入内容运营的常规互动形态清单。"}]},{"key":"0810-0816","meta":{"weekLabel":"2026年 08.10–08.16 期","range":"2026.08.10 – 2026.08.16（本周7天）","generatedAt":"2026-08-18","sources":[{"name":"UA 内容评论区","detail":"小红书 / 抖音，共 259 条评论（快照去重）；66% 集中在1个玄学攻略帖，剔噪后有效负向 22 条","tag":"评论区"},{"name":"UA 内容作品表","detail":"本周全平台 12135 个作品声量聚合（播放 3989万 · 点赞 183万创新高 · 评论 29.7万）；Mini炫主题作品数环比暴涨47倍","tag":"内容声量"}],"sentiment":{"pos":86,"neg":22,"neu":151,"total":259},"contentVolume":{"works":12135,"play":39893121,"like":1834040,"comment":297188,"share":114216,"byChannel":[{"ch":"小红书","works":5793,"comment":0,"like":0,"play":0},{"ch":"抖音","works":3799,"comment":0,"like":0,"play":23542956},{"ch":"快手","works":2209,"comment":0,"like":0,"play":16295789},{"ch":"微博","works":285,"comment":0,"like":0,"play":19344},{"ch":"B站","works":49,"comment":0,"like":0,"play":35032}]},"noticeHtml":"本期<strong>机会与风险并存，两条主线都很清晰</strong>。<strong>【机会】营销主线成功切换并破圈</strong>：从旅拍季/狐神转向「<strong>Mini炫 + 年鸡天团（大湾鸡）联动 + 30s最炫移动秀场挑战</strong>」，Mini炫主题作品数<strong>环比暴涨47倍</strong>（29→1377 个）、播放 661万；年鸡天团联动从零起量至 369 作品/199万播放；<strong>全期点赞 183万创历史新高</strong>。明星舞蹈剪辑「精准而优雅 #金玟庭 #aespa」<strong>17.6万赞/1467评</strong>、手势舞「小事化面包大事化蛋糕 #Gee」<strong>7.7万赞</strong>——舞蹈/音乐/明星向内容带来的是高点赞破圈流量，与换装展示的高播放形成互补，<strong>破圈方向获得实证</strong>。<strong>【风险】抽卡焦虑连续第5期未缓解</strong>：新品预告又是黑卡引发不满（“没白皮差评”“黑卡最难抽了”“我感觉比星罗难”“黑卡的全部不能兑换”），叠加“抽300没衣服”“300抽无大件”，且 <strong>0713 期的「卡衣服」问题本期复现</strong>。上期发现的成团“小号绕”已成社区通用词（评论区直接以“小号绕”作答），说明该绕过行为已固化。带 <strong style=\"color:#e8734a\">✦新</strong> 角标的为本期新出现（对比上期 08.03–08.09）。","isBaseline":false},"modules":[{"key":"biz","name":"商业化","desc":"抽卡奖池 / 定价与保底 / 兑换体系 / 付费福利 / 支付链路"},{"key":"activity","name":"活跃活动","desc":"活动玩法 / 任务门槛 / 奖励节奏 / 参与体验"},{"key":"ip","name":"市场IP","desc":"题材IP / 联动 / 达人内容 / 二创生态 / 声量表现"},{"key":"system","name":"本地化（系统玩法）","desc":"系统功能 / 玩法机制 / 客户端体验 / 机型兼容"},{"key":"other","name":"其他","desc":"社区氛围 / 账号交易 / 客服反馈 / 未归类诉求"}],"issues":[{"id":"biz-01","module":"biz","priority":"P0","isNew":false,"title":"新品预告又是黑卡引发不满，抽卡焦虑连续第5期未缓解","summary":"「新品预告居然是黑卡！」帖聚集 27 条评论、含 2 条强负向，玩家反应集中在三点：① 期待的白皮没有——「没白皮差评」（情感值 -0.996）；② 黑卡难度感知最高——「黑卡最难抽了」、「我感觉比星罗难」；③ 黑卡内容不可兑换——「黑卡的怎么能换」、「黑卡的全部不能」。叠加抽卡实录「抽300没衣服」、「300抽无大件」、「还差500多次到V7保底衣服图鉴」。抽卡成本焦虑自 07.06 期首次出现，已连续第5期，本期升级为对新品类型选择（又是黑卡）的直接不满。","mentions":22,"sources":["评论区"],"sentiment":"负","quotes":["没白皮差评（情感值 -0.996）","黑卡最难抽了 / 我感觉比星罗难","抽300没衣服 快帮我 / 300抽无大件的我来申一个","还差500多次到V7保底衣服图鉴 算黑吗，不太懂黑卡"],"action":"【连续5期同源，强烈建议专项立项】① 复盘新品类型排期，避免连续高难度卡池挤压普通玩家获得感，玩家已明确点名想要白皮；② 黑卡内容不可兑换这一限制需评估合理性，是当前不满的直接触点；③ 建立跨期跟踪：抽卡焦虑已从单奖池吐槽→保底质疑→商业化整体质疑→新品类型不满，逐期升级而非缓解，需结构性方案。"},{"id":"biz-02","module":"biz","priority":"P1","isNew":false,"title":"「卡衣服」问题复现（0713期老问题），且玄学攻略帖连续第3期霸榜","summary":"0713 期首次识别的「卡衣服」本期在评论区复现：「卡衣服了礼申」（情感值 -0.955）。同时「返场甄选抽奖方法〔玄学〕」单帖聚集 172 条评论，是本期评论量第一（占66%），连续第3期成为评论量霸榜帖。玩家在攻略帖下排队求助并自述战绩（「已四连 礼申 抽300没衣服」），说明玄学攻略已成为抽卡的固定配套需求。拆开看是稳定的高互动内容资产，合并看则是抽卡不确定性长期未解的侧写。","mentions":172,"sources":["评论区"],"sentiment":"中","quotes":["卡衣服了礼申（情感值 -0.955，0713期老问题复现）","「返场甄选抽奖方法〔玄学〕」单帖 172 条评论，连续第3期评论量第一","已四连 礼申 抽300没衣服 快帮我","宝宝们作品已限时了勿申，不理哈（攻略作者被申领量压到需要声明）"],"action":"① 「卡衣服/卡配件」跨期复现已达3次，建议纳入奖池设计规范做结构性修正（长尾件独立保底或碎片兑换）；② 玄学攻略帖连续霸榜说明需求刚性，可与攻略作者建立官方合作，用透明概率说明承接需求、减少玄学误导。"},{"id":"act-01","module":"activity","priority":"P0","isNew":true,"title":"★营销主线成功切换：Mini炫 + 30s秀场挑战作品数暴涨47倍","summary":"本期最大的正向变化。营销主线从旅拍季/狐神切换到 Mini炫 与 30s最炫移动秀场挑战，起量极为迅猛：Mini炫主题作品数由上期 29 个暴涨到 1377 个（约47倍）、播放 661万、点赞 26.5万；30s秀场挑战由 8 个增至 49 个、播放 46.5万。头部作品「Lucifer运镜Mini炫 30s秀场 这个运镜太爽了」91.8万播放、「Mini炫一夏～」1631条评论、「鹅娘（ai团播版）在Mini炫和年鸡天团同台」100.9万播放。新玩法+挑战赛的组合有效激活了达人与UGC产能。","mentions":12,"sources":["内容声量"],"sentiment":"正","quotes":["Mini炫：作品 29→1377 个（约47倍）、播放 661万、点赞 26.5万","Lucifer运镜Mini炫 30s秀场 这个运镜太爽了（抖音 91.8万播放 / 163评论）","Mini炫一夏～ #30s最炫移动秀场挑战（抖音 44.4万播放 / 1631评论）","鹅娘也是好上了，在Mini炫和年鸡天团同台（抖音 100.9万播放）"],"action":"【已验证有效，建议加大投入】① 拆解 30s秀场挑战的低门槛参与机制（运镜模板+短时长+挑战赛激励），作为标准化UGC放量工具复用；② Mini炫承接旅拍季成为暑期档后半主线，需保证素材与话题持续供给；③ 记录本次「新玩法+挑战赛+达人运镜教学」的起量路径，作为后续新玩法上线的标准打法。"},{"id":"act-02","module":"activity","priority":"P1","isNew":true,"title":"年鸡天团（大湾鸡）联动落地，免费获取+攻略讲解驱动参与","summary":"「炫舞手游 × 年鸡天团」联动本期从零起量至 369 个作品 / 199万播放 / 5.7万赞。传播以「可兑换 + 免费获取」为核心卖点：达人「新活动大湾鸡同款联动可爱套装宝子们可以兑换了！湾区顶流空降炫舞，除此之外还有璀璨超凡免费获取」（37.7万播放）、「新活动〖大弯鸡〗获取讲解攻略🔥 呆萌的大弯鸡盘它」（33.5万播放 / 54评论）。联动+免费获取的组合与商业化侧的黑卡焦虑形成有效对冲。","mentions":8,"sources":["内容声量"],"sentiment":"正","quotes":["年鸡天团联动：369 作品 / 199万播放 / 5.7万赞（从零起量）","新活动大湾鸡同款联动可爱套装宝子们可以兑换了! 湾区顶流空降炫舞…还有璀璨超凡免费获取（37.7万播放）","新活动〖大弯鸡〗获取讲解攻略🔥 呆萌的大弯鸡盘它（33.5万播放）"],"action":"沉淀「联动IP + 免费可兑换套装 + 达人攻略讲解」的三件套打法；本期该组合在抽卡焦虑高发期提供了正向对冲，建议在后续高难度卡池上线周同步配置免费获取活动。"},{"id":"ip-01","module":"ip","priority":"P0","isNew":true,"title":"★破圈实证：明星舞蹈/手势舞类内容跑出17.6万赞，点赞创历史新高","summary":"本期出现与以往完全不同的内容形态并取得突破：明星舞蹈剪辑「精准而优雅 #金玟庭 #金旼炡 #aespa」抖音 101万播放但点赞高达 17.6万、评论 1467 条；手势舞「小事化面包 大事化蛋糕 #Gee #手势舞」70.5万播放 / 7.6万赞 / 404评论。这两条的点赞率远超传统换装内容（通常播放数十万对应千级赞），直接推动全期点赞冲到 183万创历史新高。说明音乐/舞蹈/明星向内容能触达换装核心圈之外的泛娱乐人群，是可放大的破圈路径。","mentions":10,"sources":["内容声量"],"sentiment":"正","quotes":["精准而优雅 #金玟庭 #aespa（抖音 101万播放 / 17.6万赞 / 1467评论）","小事化面包 大事化蛋糕 #Gee #手势舞（抖音 70.5万播放 / 7.6万赞 / 404评论）","全期点赞 183万，创历史新高"],"action":"【机会信号，建议立即复用】① 舞蹈/音乐/手势舞方向定向招募泛娱乐达人（非游戏垂类），以高点赞率作为破圈效率指标；② 结合 Mini炫 舞蹈玩法本身的属性，把「游戏内舞蹈 + 流行音乐/明星编舞」做成常规内容位；③ 注意版权合规边界（明星素材、音乐授权）。"},{"id":"ip-02","module":"ip","priority":"P1","isNew":false,"title":"达人「虚伪」再出爆款，狐神情绪叙事线稳定产出百万播放","summary":"上期跑出 234万播放爆款的达人「虚伪」本期继续验证稳定性：「伤害我妹妹的都该消失」抖音 174.9万播放 / 1.4万赞 / 224评论，同系列另一条 110万播放；另有「你是我的」38.8万播放。达人「溺亡」「快放了那只狐狸」37.5万播放。狐神IP虽整体声量回落（544作品/10.4万播放），但情绪叙事+护妹/守护类剧情在头部持续有效。","mentions":8,"sources":["内容声量"],"sentiment":"正","quotes":["伤害我妹妹的都该消失（抖音 174.9万播放 / 1.4万赞 / 224评论）","快放了那只狐狸（抖音 37.5万播放 / 96评论）","你是我的 #炫舞手游0807稀世勿忘三生（抖音 38.8万播放）"],"action":"深度绑定已连续两期产出百万级爆款的达人「虚伪」，给予素材/新品优先支持；「守护/护妹」情绪母题已验证两次有效，可作为剧情向达人的选题指引。"},{"id":"sys-01","module":"system","priority":"P1","isNew":true,"title":"疑似功能异常：徽章已获得但名片无法主动带人","summary":"玩家在评论区提出明确的功能疑问：「我想问一下，朋友们，徽章抽到了，为啥名片不能主动带人了？？？」（三个问号体现困惑与不满）。这可能是名片带人功能的规则变更未告知，或存在实际 bug。该问题被夹在攻略帖评论中、未获解答，属容易被忽略但影响付费物品使用体验的信号。","mentions":3,"sources":["评论区"],"sentiment":"负","quotes":["我想问一下，朋友们，徽章抽到了，为啥名片不能主动带人了？？？"],"action":"【建议排查】核实名片「主动带人」功能的当前规则与近期是否有变更：若为 bug 需修复；若为有意调整需在游戏内明确告知（涉及付费物品的功能变更，未告知易引发信任问题）。"},{"id":"oth-01","module":"other","priority":"P1","isNew":true,"title":"「小号绕」已成社区通用词，成团绕过行为固化","summary":"上期（07.27–08.02）识别的成团活动小号攻略，本期已固化为社区通用术语：评论区出现两次以「小号绕」三个字直接作答，无需任何解释即可被理解。这说明用小号跨区绕过成团社交门槛的做法已在玩家间形成共识与标准操作，上期提出的「社交裂变目标实质落空」问题不仅未改善，反而沉淀为社区常识。","mentions":4,"sources":["评论区"],"sentiment":"中","quotes":["小号绕（评论区出现2次，作为无需解释的通用答案）","（上期原始攻略）不要自己建团，切没上过号的其他大区…建议创个不玩的大区"],"action":"【上期P0问题的跟进证据】成团社交门槛的绕过行为已固化，建议在下个成团类活动前完成设计复核：或降低强制社交门槛、或改为可选加成，同时评估跨区小号对活动成本与公平性的影响。"},{"id":"oth-02","module":"other","priority":"P2","isNew":true,"title":"账号交易帖出现在监测内容中，需关注社区治理","summary":"本期监测到账号出售帖「QQ炫舞➗号 带q」（6条评论），内容含详细的账号资产描述与议价信息：「号很白，稀世出的时候每次都不到300，几乎都是小氪就能出件，上个月一共不到10元出了三个大件，2020年自用号，因个人原因不玩了才决定卖，只走平台，不私交易，可小刀」。属账号交易灰产内容在社交平台的自然扩散。","mentions":6,"sources":["评论区"],"sentiment":"中","quotes":["QQ炫舞➗号 带q（账号出售帖标题）","号很白…2020年自用号，因个人原因不玩了才决定卖，只走平台，不私交易，可小刀","定制脸也多 各种风格都有 / 还有很多小体衣服徽章"],"action":"同步安全/运营团队关注站外账号交易的规模与话术特征；此类内容也侧面反映稀有外观资产的二级市场价值，可作为资产保值感知的参考信号。"}]}];
